const names={home:'Home / Automation Library',new:'New Flow / Recording Setup',record:'Live Recorder',designer:'Flow Designer',objects:'Object Repository',data:'Data & Variables',replay:'Replay / Training Studio',runs:'Run / Execution Console',performance:'Performance Studio',scripts:'Script / Developer Studio',settings:'Settings / Runtime'};
let flows=[]; let activeFlowId=null; let activeStartUrl=''; let recTargetFlowId=null; let recorderTimer=null; let latestRecordingId=null; let latestSteps=[]; let hybridClients=[]; let runtimeProfile=null;
const tbody=document.getElementById('flowRows');

function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function renderFlows(list=flows){
  tbody.innerHTML='';
  list.forEach(f=>{const tr=document.createElement('tr'),cls=(f.status||'Draft').toLowerCase();const rate=f.success_rate==null?'—':`<b>${f.success_rate}%</b><div class="progress"><span style="width:${f.success_rate}%"></span></div>`;tr.innerHTML=`<td><b>${esc(f.name)}</b></td><td>${esc(f.description)}</td><td><span class="pill ${cls}">${esc(f.status)}</span></td><td>${esc(f.last_run||'—')}</td><td>${rate}</td><td><span class="avatar" style="width:24px;height:24px;font-size:8px">${esc(f.owner||'EA')}</span></td>`;tr.dataset.flowId=f.id;tr.ondblclick=()=>{activeFlowId=f.id;recTargetFlowId=f.id;activeStartUrl=f.starting_url||'';const rn=document.getElementById('recName'),ru=document.getElementById('recUrl');if(rn)rn.value=f.name;if(ru&&f.starting_url)ru.value=f.starting_url;go('record')};tbody.appendChild(tr);});
  syncRecorderFlowSelect();
  if(typeof designerSyncFlowSelect==='function') designerSyncFlowSelect();
  if(typeof phase8SyncFlow==='function') phase8SyncFlow();
  if(typeof phase9SyncFlow==='function') phase9SyncFlow();
}
const WEBFLOW_API_BASE=(window.WEBFLOW_API_BASE||document.body?.dataset?.apiBase||'').replace(/\/$/,'');
function webflowUrl(path){return WEBFLOW_API_BASE&&String(path).startsWith('/')?WEBFLOW_API_BASE+path:path}
function webflowAssetUrl(path){if(!path)return '';const p=String(path);return p.startsWith('/data/')?webflowUrl(p):p.startsWith('data/')?webflowUrl('/'+p):p}
async function api(path,opts={}){const res=await fetch(webflowUrl(path),{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});const data=await res.json().catch(()=>({}));if(!res.ok){const e=new Error(data.message||data.error||`HTTP ${res.status}`);e.data=data;throw e;}return data;}
async function governedMutation(path,payload,confirmLabel='Run this WebFlow?'){
  try{return await api(path,{method:'POST',body:JSON.stringify(payload||{})})}
  catch(e){
    if(e.data?.error==='confirmation_required'){
      const risk=e.data?.risk?.reason||'This flow may change application state.';
      if(confirm(`${confirmLabel}

${risk}`)){
        return await api(path,{method:'POST',body:JSON.stringify({...payload,confirmed:true})});
      }
      const cancelled=new Error('Cancelled — no action was submitted.');cancelled.cancelled=true;throw cancelled;
    }
    throw e;
  }
}
async function loadFlows(){try{flows=await api('/api/flows');renderFlows();if(document.getElementById('home')?.classList.contains('active'))loadHomeDashboard();}catch(e){toast('Could not load persisted flows');console.error(e);}}

// Hybrid v3: the Home workspace no longer renders demo numbers/activity. All
// summary values below come from persisted flows and actual execution history.
let homeRuns=[];
function homeStateSuccess(state){return ['completed','success','succeeded','passed'].includes(String(state||'').toLowerCase())}
function homeStateLabel(state){const v=String(state||'unknown').toLowerCase();return ({completed:'Completed',success:'Completed',succeeded:'Completed',passed:'Completed',failed:'Failed',cancelled:'Cancelled',cancelling:'Cancelling',running:'Running',starting:'Starting'}[v]||String(state||'Unknown'))}
function homePillClass(state){const v=String(state||'').toLowerCase();if(homeStateSuccess(v))return 'ready';if(v==='failed')return 'failed';if(['running','starting','cancelling'].includes(v))return 'testing';return 'draft'}
function homeDate(value){if(!value)return '—';const d=new Date(value);if(Number.isNaN(d.getTime()))return String(value);const delta=Date.now()-d.getTime(),m=Math.round(delta/60000);if(m<1)return 'just now';if(m<60)return `${m} min ago`;const h=Math.round(m/60);if(h<24)return `${h} hr${h===1?'':'s'} ago`;const days=Math.round(h/24);return days<30?`${days} day${days===1?'':'s'} ago`:d.toLocaleDateString()}
function homeDuration(ms){if(ms==null||!Number.isFinite(Number(ms)))return '—';const n=Number(ms);return n<1000?`${Math.round(n)} ms`:`${(n/1000).toFixed(n<10000?1:0)} s`}
function renderHomeRuns(){const body=document.getElementById('homeRunRows');if(!body)return;if(!homeRuns.length){body.innerHTML='<tr><td colspan="6" class="home-empty">No execution history yet. Run a WebFlow and it will appear here.</td></tr>';return}body.innerHTML=homeRuns.slice(0,20).map(r=>{const f=flows.find(x=>x.id===r.flow_id),steps=`${r.completed_steps||0}/${r.total_steps||0}`;return `<tr><td><b>${esc(f?.name||r.flow_id||'Ad-hoc run')}</b></td><td><span class="pill ${homePillClass(r.state)}">${esc(homeStateLabel(r.state))}</span></td><td>${esc(homeDate(r.started_at))}</td><td>${esc(homeDuration(r.duration_ms))}</td><td>${esc(steps)}</td><td class="run-id">${esc(r.id||'—')}</td></tr>`}).join('')}
function renderHomeStats(){const cutoff=Date.now()-30*24*60*60*1000,r30=homeRuns.filter(r=>{const d=new Date(r.started_at||0);return !Number.isNaN(d.getTime())&&d.getTime()>=cutoff}),success=r30.filter(r=>homeStateSuccess(r.state)),dur=success.map(r=>Number(r.duration_ms)).filter(Number.isFinite),development=flows.filter(f=>String(f.status||'Draft').toLowerCase()!=='ready').length;const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v};set('statTotalFlows',flows.length);set('statSuccessfulRuns',success.length);set('statDevelopment',development);set('statAvgExecution',dur.length?homeDuration(dur.reduce((a,b)=>a+b,0)/dur.length):'—')}
function renderHomeActivity(recordings=[]){const host=document.getElementById('homeRecentActivity');if(!host)return;const items=[];homeRuns.slice(0,5).forEach(r=>{const f=flows.find(x=>x.id===r.flow_id);items.push({time:r.started_at,title:f?.name||r.flow_id||'WebFlow execution',text:`Execution ${homeStateLabel(r.state).toLowerCase()}${r.duration_ms!=null?` · ${homeDuration(r.duration_ms)}`:''}`})});recordings.slice(0,3).forEach(r=>items.push({time:r.ended_at||r.started_at,title:r.flow_name||'Browser recording',text:`Recording saved · ${r.steps||0} step${r.steps===1?'':'s'}`}));items.sort((a,b)=>new Date(b.time||0)-new Date(a.time||0));host.innerHTML=items.length?items.slice(0,6).map(x=>`<div class="activity-row"><b>${esc(x.title)}</b><br>${esc(x.text)}<small>${esc(homeDate(x.time))}</small></div>`).join(''):'<div class="home-empty">No WebFlow activity yet. Record or run a flow to populate this panel.</div>'}
async function loadHomeDashboard(){try{const [runs,recordings]=await Promise.all([api('/api/runs'),api('/api/recordings')]);homeRuns=Array.isArray(runs)?runs:[];renderHomeRuns();renderHomeStats();renderHomeActivity(Array.isArray(recordings)?recordings:[])}catch(e){console.warn('Home dashboard',e);const host=document.getElementById('homeRecentActivity');if(host)host.innerHTML='<div class="home-empty">Could not load execution activity.</div>'}}
function setHomeTab(tab){document.querySelectorAll('[data-home-tab]').forEach(b=>b.classList.toggle('active',b.dataset.homeTab===tab));const fv=document.getElementById('homeFlowsView'),rv=document.getElementById('homeRunsView');if(fv)fv.hidden=tab!=='flows';if(rv)rv.hidden=tab!=='runs';if(tab==='runs')renderHomeRuns()}
document.querySelectorAll('[data-home-tab]').forEach(b=>b.addEventListener('click',()=>setHomeTab(b.dataset.homeTab)));
document.getElementById('refreshHome')?.addEventListener('click',()=>{loadFlows();loadHomeDashboard()});
function go(id){document.querySelectorAll('.workspace').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===id));const w=document.getElementById(id);if(w)w.classList.add('active');document.getElementById('crumb').textContent=names[id]||id;location.hash=id;document.querySelector('.content').scrollTop=0;if(id==='home'){loadHomeDashboard();}if(id==='record'){loadHybridClients();refreshRecorder();}if(id==='objects'){loadObjects();}if(id==='data'){phase6LoadSources();}if(id==='designer'){designerLoad();}if(id==='scripts'&&typeof phase8LoadScript==='function'){phase8LoadScript();}if(id==='performance'&&typeof phase9Load==='function'){phase9Load();}if(id==='runs'&&typeof phase10Load==='function'){phase10Load();}if(id==='settings'&&typeof phase10LoadSettings==='function'){phase10LoadSettings();if(typeof phase11LoadRuntime==='function')phase11LoadRuntime();if(typeof phase13LoadProviders==='function')phase13LoadProviders();if(typeof phase14LoadGovernance==='function')phase14LoadGovernance();if(typeof loadHybridClients==='function')loadHybridClients();}}
document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>{if(x.dataset.view==='record')recTargetFlowId=null;go(x.dataset.view)});document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>{if(x.dataset.go==='record')recTargetFlowId=null;go(x.dataset.go)});

