document.getElementById('createFlow')?.addEventListener('click',()=>{const name=document.getElementById('newFlowName').value.trim();const starting_url=document.getElementById('newFlowUrl').value.trim();if(!name){toast('Enter a recording / flow name');return;}const rn=document.getElementById('recName'),ru=document.getElementById('recUrl');if(rn)rn.value=name;if(ru&&starting_url)ru.value=starting_url;activeFlowId=null;recTargetFlowId=null;activeStartUrl=starting_url;toast('Recording setup ready — the Draft WebFlow will be created when you stop recording');go('record');});

function syncRecorderFlowSelect(){/* Legacy no-op: recording is now allowed before flow creation. */}

async function loadHybridClients(){
  try{
    const [rt,clients,pkg]=await Promise.all([api('/api/runtime'),api('/api/hybrid/clients'),api('/api/hybrid/client-package').catch(()=>({}))]);
    runtimeProfile=rt.profile||{}; hybridClients=clients||[];
    const packageHint=document.getElementById('localClientPackageHint');
    if(packageHint)packageHint.textContent=pkg.exe_available?'Ready-to-pair signed EXE bundle is available. Extract it and double-click WebFlowLocalClient.exe.':'Developer package is available. Drop WebFlowLocalClient.exe into client-dist/ to serve the one-click EXE bundle.';
    const sel=document.getElementById('recClientSelect');
    if(sel){
      const current=sel.value;const opts=[];
      if(!runtimeProfile.cloud_foundry)opts.push('<option value="">This workstation (embedded local recorder)</option>');
      hybridClients.forEach(c=>opts.push(`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.state||'offline')}</option>`));
      sel.innerHTML=opts.join('')||'<option value="">No paired Local Client</option>';
      if([...sel.options].some(o=>o.value===current))sel.value=current;
    }
    const help=document.getElementById('recClientHelp');if(help)help.textContent=runtimeProfile.cloud_foundry?'Hosted Studio: Chromium remains on a paired Local Client; Studio receives only signed WebFlow events/artifacts.':'Standalone: use this workstation directly, or select a paired Local Client to test the hosted-client path.';
    renderHybridClientList();if(typeof phase5SyncRunClients==='function')phase5SyncRunClients();
  }catch(e){console.warn('Hybrid clients',e)}
}
function hybridClientOnline(c){if(!c?.last_seen)return false;return (Date.now()-new Date(c.last_seen).getTime())<15000}
function renderHybridClientList(){
  const host=document.getElementById('hybridClientList'),pill=document.getElementById('hybridClientPill');if(!host)return;
  const online=hybridClients.filter(hybridClientOnline);if(pill){pill.textContent=`${online.length} online / ${hybridClients.length} paired`;pill.className='pill '+(online.length?'ready':hybridClients.length?'testing':'draft')}
  host.innerHTML=hybridClients.length?hybridClients.map(c=>`<div class="runtime-check"><span class="pill ${hybridClientOnline(c)?'ready':'draft'}">${hybridClientOnline(c)?'online':'offline'}</span><div><b>${esc(c.name)}</b><small>${esc((c.capabilities||[]).join(', ')||'Awaiting first heartbeat')} · paired by ${esc(c.paired_by||'—')}</small></div></div>`).join(''):'<div class="placeholder mini">No Local Clients paired yet.</div>';
}
document.getElementById('recUrl')?.addEventListener('input',e=>e.target.dataset.userEdited='1');
function actionLabel(a){return({navigate:'Navigate',click:'Click',input:'Input',select:'Select',change:'Change',check:'Check',key:'Key'}[a]||a||'Event')}
function objectName(step){const t=step.target||{};return t.label||t.aria_label||t.text||t.name||t.id||t.tag||step.page_title||'Page object'}
function locator(step){const s=step?.target?.selectors||[];return s[0]?.value||'—'}
function renderRecorderSteps(recording){latestSteps=recording?.steps||[];const box=document.getElementById('recordedSteps');const count=document.getElementById('recCount');if(!box)return;count.textContent=`${latestSteps.length} step${latestSteps.length===1?'':'s'}`;count.className=`pill ${latestSteps.length?'ready':'draft'}`;if(!latestSteps.length){box.innerHTML='<div class="placeholder mini"><div class="big">◉</div>Interact with the controlled browser to capture steps.</div>';return;}box.innerHTML=latestSteps.slice().reverse().map((s,ri)=>{const idx=latestSteps.length-1-ri;const val=s.secret?'••••••••':(s.value||s.key||'');return `<div class="step ${ri===0?'active':''}" data-step-index="${idx}"><b>${String(s.sequence).padStart(2,'0')} ${esc(actionLabel(s.action))}</b>${esc(objectName(s))}<span class="step-meta">${esc(locator(s))}${val?` • <span class="step-value">${esc(val)}</span>`:''}</span></div>`}).join('');box.querySelectorAll('.step').forEach(el=>el.onclick=()=>selectRecordedStep(Number(el.dataset.stepIndex)));selectRecordedStep(latestSteps.length-1);}
function selectRecordedStep(i){const step=latestSteps[i];if(!step)return;document.querySelectorAll('#recordedSteps .step').forEach(x=>x.classList.remove('active'));const reverseIndex=latestSteps.length-1-i;document.querySelectorAll('#recordedSteps .step')[reverseIndex]?.classList.add('active');const inspector=document.getElementById('objectInspector');const t=step.target||{};const val=step.secret?'••••••••':(step.value??step.key??'—');inspector.innerHTML=`<div class="field"><label>Captured Object</label><input value="${esc(objectName(step))}" readonly></div><div class="field"><label>Action</label><input value="${esc(actionLabel(step.action))}" readonly></div><div class="field"><label>Primary Locator Candidate</label><input value="${esc(locator(step))}" readonly></div><div class="field"><label>Captured Value</label><input value="${esc(val)}" readonly></div><div class="field"><label>Page / URL</label><input value="${esc(step.page_url||'—')}" readonly></div><label style="font-size:9px;color:#6b7d91">Phase 3 classification</label><div class="chips" style="margin-top:6px"><span class="chip muted">Input</span><span class="chip muted">Output</span><span class="chip muted">Assertion</span><span class="chip muted">Secret</span><span class="chip muted">Loop Anchor</span></div>`;if(step.screenshot)showScreenshot(step.screenshot);}
function showScreenshot(src){const p=document.getElementById('browserPreview');if(!p)return;p.classList.add('has-shot');p.innerHTML=`<img src="${esc(webflowAssetUrl(src))}?t=${Date.now()}" alt="Latest recorder screenshot">`;}
function setRecorderUI(st){const state=document.getElementById('recState');const start=document.getElementById('startRec'),pause=document.getElementById('pauseRec'),stop=document.getElementById('stopRec'),hint=document.getElementById('recHint'),liveUrl=document.getElementById('liveUrl');const s=st?.state||'idle';state.textContent=s[0].toUpperCase()+s.slice(1);state.className=`pill ${s==='recording'?'ready':s==='error'?'failed':s==='paused'?'testing':'draft'}`;start.disabled=['starting','recording','paused','stopping'].includes(s);pause.disabled=!['recording','paused'].includes(s);pause.textContent=s==='paused'?'Resume':'Pause';stop.disabled=!['starting','recording','paused'].includes(s);if(liveUrl)liveUrl.textContent=st?.url||'No active controlled browser session';const remote=st?.execution_location==='local-client';if(st?.error){hint.textContent=st.error;hint.classList.add('rec-error')}else{hint.classList.remove('rec-error');hint.textContent=s==='recording'?(remote?'Recording on paired Local Client; signed step snapshots are syncing to Studio.':'Recording real browser events on this workstation.'):s==='paused'?'Capture is paused; the local browser remains open.':s==='stopped'?'Recording saved and promoted to a Draft WebFlow.':remote?'Waiting for the paired Local Client to accept the signed recording task.':'A controlled Chromium window will open on this workstation.';}if(st?.recording_id)latestRecordingId=st.recording_id;if(st?.latest_screenshot)showScreenshot(st.latest_screenshot);}
async function refreshRecorder(){try{const st=await api('/api/recorder/status');setRecorderUI(st);if(st.recording_id){const rec=await api('/api/recordings/'+st.recording_id);renderRecorderSteps(rec);}if(['stopped','error','idle'].includes(st.state)&&recorderTimer){clearInterval(recorderTimer);recorderTimer=null;if(st.state==='stopped'){loadFlows();loadHybridClients();}}return st;}catch(e){console.warn(e);}}
function startRecorderPoll(){clearInterval(recorderTimer);recorderTimer=setInterval(refreshRecorder,700)}
document.getElementById('startRec')?.addEventListener('click',async()=>{const recording_name=document.getElementById('recName')?.value.trim()||'New WebFlow Recording';const url=document.getElementById('recUrl').value.trim();const client_id=document.getElementById('recClientSelect')?.value||'';if(!url){toast('Enter a starting URL');return;}if(runtimeProfile?.cloud_foundry&&!client_id){toast('Pair and select a Local Client first');return;}try{latestRecordingId=null;latestSteps=[];renderRecorderSteps({steps:[]});setRecorderUI({state:'starting',url,execution_location:client_id?'local-client':'embedded-local'});const st=await api('/api/recorder/start',{method:'POST',body:JSON.stringify({recording_name,url,client_id,flow_id:recTargetFlowId||null})});setRecorderUI(st);startRecorderPoll();toast(client_id?'Recording request sent to Local Client':'Controlled Chromium recording started');}catch(e){setRecorderUI({state:'error',error:e.message});if(e.data?.error==='playwright_not_installed')info('Playwright setup required',e.message);else if(e.data?.error==='local_client_required')info('Local Client required',e.message);else toast(e.message);}});
document.getElementById('pauseRec')?.addEventListener('click',async()=>{try{const current=await api('/api/recorder/status');const endpoint=current.state==='paused'?'/api/recorder/resume':'/api/recorder/pause';const client_id=document.getElementById('recClientSelect')?.value||current.client_id||'';const st=await api(endpoint,{method:'POST',body:JSON.stringify({client_id})});setRecorderUI(st);toast(st.state==='paused'?'Recording paused':'Recording resumed');}catch(e){toast(e.message)}});
document.getElementById('stopRec')?.addEventListener('click',async()=>{try{const current=await api('/api/recorder/status').catch(()=>({}));const client_id=document.getElementById('recClientSelect')?.value||current.client_id||'';const st=await api('/api/recorder/stop',{method:'POST',body:JSON.stringify({client_id})});setRecorderUI(st);startRecorderPoll();toast(st.state==='stopped'?'Recording stopped and saved.':'Stopping recording…');setTimeout(async()=>{const final=await refreshRecorder();if(final?.state==='stopping')toast('Browser cleanup is still finishing; WebFlow will recover it automatically.');},5000);}catch(e){toast(e.message)}});

