let deferredInstall=null;const installBtn=document.getElementById('installApp');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;if(installBtn)installBtn.hidden=false;});installBtn?.addEventListener('click',async()=>{if(!deferredInstall){toast('Install is available when browser PWA criteria are met');return;}deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;installBtn.hidden=true;});window.addEventListener('appinstalled',()=>toast('ALM WebFlow Studio installed'));if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(console.warn));}
async function checkRuntime(){try{const h=await api('/api/health');const el=document.getElementById('apiHealth');if(el){el.textContent=`API ${h.phase} • ${h.hybrid_clients||0} local client${h.hybrid_clients===1?'':'s'}`;el.className=`pill ${h.playwright||h.hybrid_clients?'ready':'testing'}`;}}catch(e){const el=document.getElementById('apiHealth');if(el){el.textContent='API Offline';el.className='pill failed';}}}
