// Phase 3 — persistent Object Repository & recorder classifications.
let objects=[]; let activeObjectId=null; let selectedRecordedStepIndex=null; let objectRecordings=[]; let objectGroupMode='recording';
async function loadObjects(rebuild=false){
  try{[objects,objectRecordings]=await Promise.all([api(rebuild?'/api/objects/rebuild':'/api/objects',rebuild?{method:'POST',body:'{}'}:{}),api('/api/recordings')]);renderObjects();}
  catch(e){console.warn(e);toast(`Object repository: ${e.message}`)}
}
function stabilityClass(n){return n>=90?'ready':n>=70?'testing':'failed'}
function objectRecordingName(id){const r=objectRecordings.find(x=>x.id===id);return r?.recording_name||r?.flow_name||(id?`Recording ${String(id).slice(0,8)}`:'Unassigned')}
function renderObjects(){
  const rows=document.getElementById('objectRows'),count=document.getElementById('objectCount');if(!rows||!count)return;
  count.textContent=`${objects.length} object${objects.length===1?'':'s'}`; count.className=`pill ${objects.length?'ready':'draft'}`;
  const groupSelect=document.getElementById('objectGroupMode');if(groupSelect)groupSelect.value=objectGroupMode;
  if(!objects.length){rows.innerHTML='<tr><td colspan="5">No captured objects yet. Record and stop a web process, then return here.</td></tr>';renderObjectDetail(null);return;}
  const grouped={};for(const o of objects){const key=objectGroupMode==='label'?(o.group_label||'Unlabeled'):objectRecordingName(o.source_recording_id);(grouped[key]??=[]).push(o)}
  rows.innerHTML=Object.keys(grouped).sort((a,b)=>a.localeCompare(b)).map(group=>`<tr class="object-group-row"><td colspan="5"><b>${esc(group)}</b><span>${grouped[group].length} object(s)</span></td></tr>`+grouped[group].sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''))).map(o=>`<tr data-object-id="${esc(o.id)}" class="${o.id===activeObjectId?'selected-row':''}"><td><b>${esc(o.name)}</b><div class="subtle">${esc(o.accessible_name||o.page_title||'')}</div></td><td>${esc(o.type||'Element')}</td><td class="mono-cell">${esc(o.primary_locator||'—')}</td><td><span class="pill ${stabilityClass(Number(o.stability||0))}">${Number(o.stability||0)}%</span></td><td>${Number(o.capture_count||1)}×</td></tr>`).join('')).join('');
  rows.querySelectorAll('tr[data-object-id]').forEach(r=>r.onclick=()=>{activeObjectId=r.dataset.objectId;renderObjects();renderObjectDetail(objects.find(o=>o.id===activeObjectId));});
  if(!activeObjectId||!objects.some(o=>o.id===activeObjectId))activeObjectId=objects[0].id;
  renderObjectDetail(objects.find(o=>o.id===activeObjectId));
}
async function renderObjectDetail(o){
  const box=document.getElementById('objectDetail'),pill=document.getElementById('objectStability');if(!box)return;
  if(!o){box.innerHTML='<div class="placeholder mini">Select a captured object.</div>';pill.textContent='—';pill.className='pill draft';return;}
  pill.textContent=`${o.stability||0}% stable`;pill.className=`pill ${stabilityClass(Number(o.stability||0))}`;
  let diag={ranked_selectors:o.selectors||[],warnings:[]};try{diag=await api(`/api/objects/${o.id}/diagnostics`)}catch(e){}
  const options=(diag.ranked_selectors||[]).map(s=>`<option value="${esc(s.value)}" ${s.value===o.primary_locator?'selected':''}>${esc(s.kind)} • ${esc(s.value)} • ${s.score}%</option>`).join('');
  const warnings=(diag.warnings||[]).map(x=>`<div class="selector-warning">⚠ ${esc(x)}</div>`).join('')||'<div class="selector-ok">✓ Locator set has a strong primary candidate.</div>';
  box.innerHTML=`<div class="field"><label>Friendly Name</label><input id="objName" value="${esc(o.name)}"></div><div class="field"><label>Type</label><input value="${esc(o.type||'Element')}" readonly></div><div class="field"><label>Accessible Name</label><input value="${esc(o.accessible_name||'—')}" readonly></div><div class="field"><label>Primary Locator</label><select id="objPrimary">${options}</select></div><div class="selector-list">${(diag.ranked_selectors||[]).map(s=>`<div><span class="selector-score ${stabilityClass(Number(s.score||0))}">${s.score}%</span><b>${esc(s.kind)}</b><code>${esc(s.value)}</code></div>`).join('')}</div>${warnings}<div class="field" style="margin-top:12px"><label>Source Recording</label><input value="${esc(objectRecordingName(o.source_recording_id))}" readonly></div><div class="field"><label>Custom Group Label</label><input id="objGroupLabel" value="${esc(o.group_label||'')}" placeholder="e.g. Login, Search, Approval"></div><div class="field"><label>Source URL</label><input value="${esc(o.page_url||'—')}" readonly></div><div class="field"><label>Notes</label><input id="objNotes" value="${esc(o.notes||'')}"></div><div class="object-actions"><button class="btn blue" id="saveObject">Save Object</button><button class="btn" id="rescoreObject">Re-score</button>${o.source_screenshot?'<button class="btn" id="showObjectShot">Source Screenshot</button>':''}</div>`;
  document.getElementById('saveObject').onclick=async()=>{try{const updated=await api(`/api/objects/${o.id}`,{method:'PUT',body:JSON.stringify({name:document.getElementById('objName').value.trim()||o.name,primary_locator:document.getElementById('objPrimary').value,notes:document.getElementById('objNotes').value,group_label:document.getElementById('objGroupLabel')?.value.trim()||''})});objects=objects.map(x=>x.id===updated.id?updated:x);renderObjects();toast('Object saved');}catch(e){toast(e.message)}};
  document.getElementById('rescoreObject').onclick=async()=>{await loadObjects(true);activeObjectId=o.id;renderObjects();toast('Locator candidates re-scored from recordings')};
  if(o.source_screenshot)document.getElementById('showObjectShot').onclick=()=>info('Source screenshot',`Captured screenshot: ${o.source_screenshot}\nBounds: ${JSON.stringify(o.bounds||{})}`);
}
document.getElementById('rebuildObjects')?.addEventListener('click',async()=>{await loadObjects(true);toast('Object Repository rebuilt')});document.getElementById('objectGroupMode')?.addEventListener('change',e=>{objectGroupMode=e.target.value;renderObjects()});

async function classifyStep(i,classification){
  const step=latestSteps[i];if(!step||!latestRecordingId)return;
  try{const updated=await api(`/api/recordings/${latestRecordingId}/steps/${step.id}/classify`,{method:'POST',body:JSON.stringify({classification})});latestSteps[i]={...step,classification:updated.classification};selectedRecordedStepIndex=i;selectRecordedStep(i);toast(classification?`Marked as ${classification}`:'Classification cleared');}
  catch(e){toast(e.message)}
}
// Enhance Phase 2 step inspector without changing its approved layout.
const phase2SelectRecordedStep=selectRecordedStep;
selectRecordedStep=function(i){
  selectedRecordedStepIndex=i;phase2SelectRecordedStep(i);const step=latestSteps[i];if(!step)return;
  const inspector=document.getElementById('objectInspector');const chips=inspector.querySelector('.chips');if(!chips)return;
  const choices=['Input','Output','Assertion','Secret','Loop Anchor','Optional'];chips.innerHTML=choices.map(c=>`<button class="chip class-chip ${step.classification===c?'selected':''}" data-classification="${esc(c)}">${step.classification===c?'✓ ':''}${esc(c)}</button>`).join('')+(step.classification?'<button class="chip class-chip muted" data-classification="">Clear</button>':'');
  chips.querySelectorAll('[data-classification]').forEach(b=>b.onclick=()=>classifyStep(i,b.dataset.classification||null));
  const label=document.createElement('div');label.className='classification-note';label.textContent=step.classification?`Classification: ${step.classification}`:'Choose how this captured object/value should behave in the future flow.';chips.after(label);
}

// Phase 4 — Replay / Training Studio uses persisted recordings, screenshots and annotations.
let replayRecordings=[], replayRecording=null, replayIndex=0, replayTimer=null;
function replayVisibleSteps(){return (replayRecording?.steps||[]).filter(s=>!s.training_hidden)}
function replayLabel(step){const t=step?.target||{};return step?.training_title||t.label||t.aria_label||t.text||t.name||t.id||t.tag||step?.action||'Recorded action'}
function defaultInstruction(step){const label=replayLabel(step);const val=(step?.secret||step?.classification==='Secret')?'the protected value':step?.value?`“${step.value}”`:'';const action=String(step?.action||'').toLowerCase();if(action==='input')return `Enter ${val||'the required value'} in ${label}.`;if(action==='click')return `Select ${label}.`;if(action==='select')return `Choose ${val||'the required option'} from ${label}.`;if(action==='check')return `Set ${label} to the recorded selection.`;if(action==='key')return `Use the ${step.key||'recorded'} key while focused on ${label}.`;if(action==='navigate')return `Navigate to ${step.page_url||label}.`;return `${String(step?.action||'Perform').replace(/^./,c=>c.toUpperCase())} ${label}.`}
async function loadReplayRecordings(){try{replayRecordings=await api('/api/recordings');const sel=document.getElementById('replayRecording');if(!sel)return;sel.innerHTML=replayRecordings.length?replayRecordings.map(r=>`<option value="${esc(r.id)}">${esc(r.recording_name||r.flow_name)} • ${r.steps} steps • ${esc((r.started_at||'').slice(0,16).replace('T',' '))}</option>`).join(''):'<option value="">No saved recordings</option>';if(replayRecordings.length){await loadReplayRecording(sel.value)}else renderReplay();}catch(e){toast(`Replay: ${e.message}`)}}
async function loadReplayRecording(id){if(!id){replayRecording=null;renderReplay();return}try{replayRecording=await api('/api/recordings/'+id);replayIndex=0;stopReplay();renderReplay();}catch(e){toast(e.message)}}
function renderReplay(){const list=document.getElementById('replayStepList'),count=document.getElementById('replayCount'),meta=document.getElementById('replayMeta');if(!list)return;const all=replayRecording?.steps||[], visible=replayVisibleSteps();if(!replayRecording){list.innerHTML='<div class="placeholder mini">No saved recording selected.</div>';count.textContent='No recording';count.className='pill draft';meta.textContent='Record and stop a process first.';renderReplayStage(null);renderReplayEditor(null);return}count.textContent=`${visible.length} training step${visible.length===1?'':'s'}`;count.className='pill ready';meta.textContent=`${all.length-visible.length} hidden • ${replayRecording.starting_url||''}`;if(replayIndex>=visible.length)replayIndex=Math.max(0,visible.length-1);list.innerHTML=all.map((s,i)=>{const vi=visible.indexOf(s);return `<div class="replay-step-item ${vi===replayIndex&&!s.training_hidden?'selected':''} ${s.training_hidden?'hidden-step':''}" data-step-id="${esc(s.id)}"><div class="replay-step-num">${i+1}</div><div><b>${esc(replayLabel(s))}</b><small>${esc(s.action||'step')}${s.classification?' • '+esc(s.classification):''}${s.training_hidden?' • hidden from training':''}</small></div></div>`}).join('');list.querySelectorAll('[data-step-id]').forEach(el=>el.onclick=()=>{const s=all.find(x=>x.id===el.dataset.stepId);if(s?.training_hidden){renderReplayEditor(s);return}const vi=visible.indexOf(s);if(vi>=0){replayIndex=vi;stopReplay();renderReplay();}});const current=visible[replayIndex]||null;renderReplayStage(current);renderReplayEditor(current)}
function shotUrl(step){let p=step?.screenshot||step?.screenshot_path||step?.source_screenshot||'';if(!p)return '';p=String(p).replace(/\\/g,'/');if(!p.startsWith('/')&&!p.startsWith('data/'))p='/data/recordings/screenshots/'+p.split('/').pop();return webflowAssetUrl(p)}
function renderReplayStage(step){const body=document.getElementById('replayBody'),url=document.getElementById('replayUrl');if(!body)return;if(!step){url.textContent='Training Replay';body.innerHTML='<div class="placeholder mini"><div class="big">▷</div>Select a recorded step.</div>';return}url.textContent=`Step ${replayIndex+1} of ${replayVisibleSteps().length} • ${step.page_url||replayRecording.starting_url||''}`;const note=step.training_note||defaultInstruction(step);const value=(step.secret||step.classification==='Secret')?'••••••••':step.value||'';const img=shotUrl(step);if(img){const b=step.target?.bounds||{};body.innerHTML=`<div class="replay-shot-wrap"><img id="replayShot" src="${esc(img)}" alt="Recorded step screenshot"><div class="replay-highlight" id="replayHighlight" hidden></div><div class="replay-caption"><b>${esc(replayLabel(step))}</b><p>${esc(note)}${value?`<br>Recorded value: <strong>${esc(value)}</strong>`:''}</p></div></div>`;const im=document.getElementById('replayShot');im.onload=()=>positionReplayHighlight(im,b);}else{body.innerHTML=`<div class="placeholder mini"><div class="big">${esc((step.action||'•').slice(0,1).toUpperCase())}</div><b>${esc(replayLabel(step))}</b><div style="margin-top:8px">${esc(note)}</div>${value?`<div style="margin-top:6px">Value: ${esc(value)}</div>`:''}<div style="margin-top:10px;color:#8495a8">No screenshot was captured for this event.</div></div>`}}
function positionReplayHighlight(img,b){const hl=document.getElementById('replayHighlight');if(!hl||!b||!b.width||!img.naturalWidth)return;const sx=img.clientWidth/img.naturalWidth,sy=img.clientHeight/img.naturalHeight;hl.style.left=`${Math.max(0,b.x*sx)}px`;hl.style.top=`${Math.max(0,b.y*sy)}px`;hl.style.width=`${Math.max(12,b.width*sx)}px`;hl.style.height=`${Math.max(12,b.height*sy)}px`;hl.hidden=false}
function renderReplayEditor(step){const box=document.getElementById('replayEditorBody'),pill=document.getElementById('replayClass');if(!box)return;if(!step){pill.textContent='—';pill.className='pill draft';box.innerHTML='<div class="placeholder mini">Select a step to edit its training guidance.</div>';return}pill.textContent=step.classification||'Recorded';pill.className=`pill ${step.classification?'testing':'draft'}`;box.innerHTML=`<div class="field"><label>Training Title</label><input id="trainingTitle" value="${esc(step.training_title||replayLabel(step))}"></div><div class="field"><label>Instruction / Annotation</label><textarea id="trainingNote">${esc(step.training_note||defaultInstruction(step))}</textarea></div><div class="replay-detail"><b>Action:</b> ${esc(step.action||'—')}<br><b>Page:</b> ${esc(step.page_title||step.page_url||'—')}<br><b>Classification:</b> ${esc(step.classification||'None')}</div><div class="editor-actions"><button class="btn blue" id="saveTrainingStep">Save Guidance</button><button class="btn" id="toggleTrainingStep">${step.training_hidden?'Show in Training':'Hide from Training'}</button><button class="btn" id="resetTrainingStep">Reset Text</button></div>`;document.getElementById('saveTrainingStep').onclick=()=>saveTrainingStep(step,{training_title:document.getElementById('trainingTitle').value.trim(),training_note:document.getElementById('trainingNote').value.trim()});document.getElementById('toggleTrainingStep').onclick=()=>saveTrainingStep(step,{training_hidden:!step.training_hidden});document.getElementById('resetTrainingStep').onclick=()=>saveTrainingStep(step,{training_title:'',training_note:''})}
async function saveTrainingStep(step,patch){try{const updated=await api(`/api/recordings/${replayRecording.id}/steps/${step.id}`,{method:'PUT',body:JSON.stringify(patch)});replayRecording.steps=replayRecording.steps.map(s=>s.id===updated.id?updated:s);if(patch.training_hidden){const visible=replayVisibleSteps();replayIndex=Math.min(replayIndex,Math.max(0,visible.length-1));}renderReplay();toast('Training step saved')}catch(e){toast(e.message)}}
function stopReplay(){clearInterval(replayTimer);replayTimer=null;const b=document.getElementById('replayPlay');if(b)b.textContent='▶ Play'}
function playReplay(){const visible=replayVisibleSteps();if(!visible.length)return;if(replayTimer){stopReplay();return}document.getElementById('replayPlay').textContent='Ⅱ Pause';const delay=Number(document.getElementById('replaySpeed').value||1800);replayTimer=setInterval(()=>{if(replayIndex>=visible.length-1){stopReplay();return}replayIndex++;renderReplay()},delay)}
document.getElementById('replayRecording')?.addEventListener('change',e=>loadReplayRecording(e.target.value));document.getElementById('replayPrev')?.addEventListener('click',()=>{stopReplay();replayIndex=Math.max(0,replayIndex-1);renderReplay()});document.getElementById('replayNext')?.addEventListener('click',()=>{stopReplay();replayIndex=Math.min(Math.max(0,replayVisibleSteps().length-1),replayIndex+1);renderReplay()});document.getElementById('replayPlay')?.addEventListener('click',playReplay);document.getElementById('exportTraining')?.addEventListener('click',()=>{if(!replayRecording){toast('Select a saved recording first');return}window.location.href=`/api/training/export/${replayRecording.id}`});
loadReplayRecordings();


// Phase 5 — executable automation engine + consistent run artifacts.
let phase5RunRecordings=[], phase5ActiveRun=null, phase5Poll=null, phase5SelectedStepId=null, phase5HybridTaskId=null;
function runStatusClass(state){if(state==='completed')return 'ready';if(['failed','cancelled'].includes(state))return 'failed';if(['running','starting','cancelling'].includes(state))return 'testing';return 'draft'}
function fmtMs(ms){if(ms==null)return '—';if(ms<1000)return `${Math.round(ms)} ms`;return `${(ms/1000).toFixed(ms<10000?2:1)} s`}
async function phase5LoadRunSources(){try{phase5RunRecordings=await api('/api/recordings');const sel=document.getElementById('runRecording');if(!sel)return;sel.innerHTML=phase5RunRecordings.length?phase5RunRecordings.map(r=>`<option value="${esc(r.id)}" data-flow="${esc(r.flow_id||'')}">${esc(r.flow_name)} • ${r.steps} recorded steps</option>`).join(''):'<option value="">No saved recordings — record a process first</option>';}catch(e){toast(`Executions: ${e.message}`)}}
function phase5SyncRunClients(){const sel=document.getElementById('runClientSelect');if(!sel)return;const old=sel.value;const opts=[];if(!runtimeProfile?.cloud_foundry)opts.push('<option value="">This workstation</option>');hybridClients.forEach(c=>opts.push(`<option value="${esc(c.id)}">${esc(c.name)} · ${hybridClientOnline(c)?'online':'offline'}</option>`));sel.innerHTML=opts.join('')||'<option value="">No Local Client available</option>';if([...sel.options].some(o=>o.value===old))sel.value=old;}
async function phase5RunnerHealth(){try{const h=await api('/api/health');const p=document.getElementById('runnerDependency');if(!p)return;p.textContent=h.executor?'Playwright Ready':'Playwright Missing';p.className=`pill ${h.executor?'ready':'failed'}`;}catch(e){}}
function phase5RunButtons(state){const active=['starting','running','cancelling'].includes(state);const run=document.getElementById('runAutomation'),cancel=document.getElementById('cancelRun'),retry=document.getElementById('retryFailedRun');if(run)run.disabled=active;if(cancel)cancel.disabled=!active;if(retry)retry.disabled=active||!phase5ActiveRun||!(phase5ActiveRun.steps||[]).some(s=>s.status==='failed')}
function phase5RenderRun(run){phase5ActiveRun=run&&run.id?run:null;const pill=document.getElementById('runPill'),summary=document.getElementById('runSummary'),bar=document.getElementById('runProgressBar'),txt=document.getElementById('runProgressText'),list=document.getElementById('runStepList'),outs=document.getElementById('runOutputs');if(!pill)return;if(!phase5ActiveRun){pill.textContent='Ready';pill.className='pill testing';summary.textContent='Select a saved recording and run it.';bar.style.width='0%';txt.textContent='0 / 0';list.innerHTML='<div class="placeholder mini">No execution started.</div>';outs.textContent='{}';phase5RunButtons('idle');return}const r=phase5ActiveRun,state=r.state||'idle',done=(r.completed_steps||0)+(r.failed_steps||0),total=r.total_steps||0,pct=total?Math.min(100,Math.round(done/total*100)):0;pill.textContent=state[0].toUpperCase()+state.slice(1);pill.className=`pill ${runStatusClass(state)}`;summary.textContent=`${r.headless?'Headless':'Headed'} • ${fmtMs(r.duration_ms)}${r.last_error?' • '+r.last_error:''}`;bar.style.width=`${pct}%`;txt.textContent=`${done} / ${total}`;outs.textContent=JSON.stringify(r.outputs||{},null,2);const steps=r.steps||[];list.innerHTML=steps.length?steps.map(s=>`<div class="run-step phase5-run-step ${s.status==='running'?'current':''} ${s.status==='failed'?'run-failed':''}" data-run-step="${esc(s.id)}"><span class="check">${s.status==='passed'?'✓':s.status==='failed'?'!':'▶'}</span><div><b>${esc(s.label||s.action||'Step')}</b><small>${esc(s.action||'')} • ${fmtMs(s.duration_ms)}${s.attempts>1?' • '+s.attempts+' attempts':''}</small></div><span class="spacer"></span><span class="pill ${s.status==='passed'?'ready':s.status==='failed'?'failed':'testing'}">${esc(s.status)}</span></div>`).join(''):'<div class="placeholder mini">Starting browser…</div>';list.querySelectorAll('[data-run-step]').forEach(el=>el.onclick=()=>{phase5SelectedStepId=el.dataset.runStep;phase5RenderArtifact(steps.find(s=>s.id===phase5SelectedStepId))});let selected=steps.find(s=>s.id===phase5SelectedStepId)||[...steps].reverse().find(s=>s.screenshot)||steps[steps.length-1];if(selected)phase5RenderArtifact(selected);phase5RunButtons(state)}
function phase5RenderArtifact(step){const body=document.getElementById('runArtifactBody'),pill=document.getElementById('runArtifactPill');if(!body||!pill)return;if(!step){pill.textContent='No artifact';pill.className='pill draft';body.innerHTML='<div class="placeholder mini"><div class="big">▣</div>Fresh screenshots from the automation run will appear here.</div>';return}pill.textContent=`Step ${step.sequence} • ${step.status}`;pill.className=`pill ${step.status==='passed'?'ready':step.status==='failed'?'failed':'testing'}`;body.innerHTML=step.screenshot?`<img class="run-artifact-img" src="${esc(webflowAssetUrl(step.screenshot))}?t=${Date.now()}" alt="Execution screenshot"><div class="run-artifact-meta"><b>${esc(step.label||step.action)}</b><div>Locator: ${esc(step.locator_used?.kind||'—')} ${esc(step.locator_used?.value||'')}</div>${step.output!=null?`<div>Output: <strong>${esc(step.output)}</strong></div>`:''}${step.error?`<div class="run-error-text">${esc(step.error)}</div>`:''}</div>`:`<div class="placeholder mini"><div class="big">▣</div>${esc(step.error||'No screenshot was available for this step.')}</div>`}
async function phase5StartRun(){const sel=document.getElementById('runRecording');if(!sel?.value){toast('Record and save a process first');return}const opt=sel.selectedOptions[0],client_id=document.getElementById('runClientSelect')?.value||'',payload={recording_id:sel.value,flow_id:opt?.dataset.flow||'',headless:document.getElementById('runBrowser').value==='true',timeout_ms:Number(document.getElementById('runTimeout').value),retries:Number(document.getElementById('runRetries').value),failure_policy:document.getElementById('runFailurePolicy').value,use_designer:true};if(runtimeProfile?.cloud_foundry&&!client_id){toast('Hosted browser execution requires a paired Local Client');return}try{phase5SelectedStepId=null;if(client_id){const task=await governedMutation('/api/hybrid/execute',{...payload,client_id},'Confirm Local Client execution?');phase5HybridTaskId=task.task_id;phase5RenderRun({id:'hybrid-'+task.task_id,state:'starting',headless:payload.headless,total_steps:0,completed_steps:0,failed_steps:0,steps:[],outputs:{},last_error:null});phase5BeginHybridPolling();toast('Signed execution dispatched to Local Client')}else{phase5HybridTaskId=null;const run=await governedMutation('/api/executor/start',payload,'Confirm direct execution?');phase5RenderRun(run);phase5BeginPolling();toast('Automation started on this workstation')}}catch(e){if(!e.cancelled)toast(e.message)}}
function phase5BeginPolling(){clearInterval(phase5Poll);phase5Poll=setInterval(async()=>{try{const r=await api('/api/executor/status');phase5RenderRun(r);if(!['starting','running','cancelling'].includes(r.state)){clearInterval(phase5Poll);phase5Poll=null;phase5LoadRunHistory();loadFlows();}}catch(e){}},650)}
function phase5BeginHybridPolling(){clearInterval(phase5Poll);phase5Poll=setInterval(async()=>{try{const t=await api('/api/hybrid/tasks/'+phase5HybridTaskId);const run=t?.result?.run;if(run)phase5RenderRun(run);else{const state=t.state==='claimed'?'running':t.state||'queued';phase5RenderRun({id:'hybrid-'+phase5HybridTaskId,state,headless:document.getElementById('runBrowser').value==='true',total_steps:0,completed_steps:0,failed_steps:0,steps:[],outputs:{},last_error:t?.result?.message||t?.result?.error||null})}if(['completed','failed'].includes(t.state)){clearInterval(phase5Poll);phase5Poll=null;phase5HybridTaskId=null;phase5LoadRunHistory();loadFlows();}}catch(e){}},700)}
async function phase5CancelRun(){try{if(phase5HybridTaskId){await api(`/api/hybrid/tasks/${phase5HybridTaskId}/cancel`,{method:'POST',body:'{}'});toast('Local Client cancellation requested');phase5BeginHybridPolling();return}const r=await api('/api/executor/cancel',{method:'POST',body:'{}'});phase5RenderRun(r);phase5BeginPolling();toast('Cancellation requested')}catch(e){toast(e.message)}}
async function phase5RetryFailed(){if(!phase5ActiveRun?.id)return;try{const r=await api(`/api/runs/${phase5ActiveRun.id}/retry-failed`,{method:'POST',body:'{}'});phase5SelectedStepId=null;phase5RenderRun(r);phase5BeginPolling();toast('Retry started from failed step')}catch(e){toast(e.message)}}
async function phase5LoadRunHistory(){try{const rows=await api('/api/runs'),tbody=document.getElementById('runHistoryRows');if(!tbody)return;tbody.innerHTML=rows.length?rows.slice(0,20).map(r=>`<tr data-run-id="${esc(r.id)}"><td>${esc((r.started_at||'').slice(0,19).replace('T',' '))}</td><td><span class="pill ${runStatusClass(r.state)}">${esc(r.state||'')}</span></td><td>${r.completed_steps||0}/${r.total_steps||0}${r.failed_steps?' • '+r.failed_steps+' failed':''}</td><td>${fmtMs(r.duration_ms)}</td><td>${r.headless?'Headless':'Headed'}</td><td class="run-history-error">${esc(r.last_error||'—')}</td></tr>`).join(''):'<tr><td colspan="6">No executions yet.</td></tr>';tbody.querySelectorAll('[data-run-id]').forEach(tr=>tr.ondblclick=async()=>{try{const r=await api('/api/runs/'+tr.dataset.runId);phase5SelectedStepId=null;phase5RenderRun(r)}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
document.getElementById('runAutomation')?.addEventListener('click',phase5StartRun);document.getElementById('cancelRun')?.addEventListener('click',phase5CancelRun);document.getElementById('retryFailedRun')?.addEventListener('click',phase5RetryFailed);document.getElementById('refreshRuns')?.addEventListener('click',phase5LoadRunHistory);
phase5LoadRunSources();phase5SyncRunClients();phase5RunnerHealth();phase5LoadRunHistory();api('/api/executor/status').then(r=>{if(r?.id){phase5RenderRun(r);if(['starting','running','cancelling'].includes(r.state))phase5BeginPolling()}}).catch(()=>{});

// Phase 6 — Excel / CSV data engine, mappings, row batches, and runtime variable injection.
let phase6Datasets=[], phase6Recordings=[], phase6Variables=[], phase6Mapping=null, phase6Batch=null, phase6BatchPoll=null;
function phase6B64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const bytes=new Uint8Array(r.result);let binary='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk)binary+=String.fromCharCode(...bytes.subarray(i,i+chunk));resolve(btoa(binary))};r.onerror=()=>reject(r.error);r.readAsArrayBuffer(file)})}
async function phase6LoadSources(){try{[phase6Recordings,phase6Datasets]=await Promise.all([api('/api/recordings'),api('/api/data/datasets')]);const rs=document.getElementById('dataRecording'),ds=document.getElementById('dataDataset');if(rs){const current=rs.value;rs.innerHTML='<option value="">Select a saved recording</option>'+phase6Recordings.map(r=>`<option value="${esc(r.id)}">${esc(r.recording_name||r.flow_name)} • ${r.steps} steps</option>`).join('');if(phase6Recordings.some(r=>r.id===current))rs.value=current}if(ds){const current=ds.value;ds.innerHTML='<option value="">Upload a workbook or CSV</option>'+phase6Datasets.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('');if(phase6Datasets.some(d=>d.id===current))ds.value=current}phase6DataHealth()}catch(e){toast('Data workspace: '+e.message)}}
async function phase6DataHealth(){try{const h=await api('/api/health'),p=document.getElementById('dataEnginePill');if(!p)return;p.textContent=h.data_engine?'Data Engine Ready':'openpyxl Missing';p.className=`pill ${h.data_engine?'ready':'failed'}`}catch(e){}}
async function phase6Upload(){const input=document.getElementById('dataFileInput'),file=input?.files?.[0];if(!file)return;try{const b64=await phase6B64(file);const d=await api('/api/data/upload',{method:'POST',body:JSON.stringify({name:file.name,content_base64:b64})});toast(`${file.name} uploaded`);await phase6LoadSources();document.getElementById('dataDataset').value=d.id;await phase6LoadDataset(d.id)}catch(e){toast(e.message)}finally{if(input)input.value=''}}
async function phase6LoadDataset(id,requestedSheet=null){const sheet=document.getElementById('dataSheet');if(!id){phase6RenderPreview(null);if(sheet)sheet.innerHTML='<option value="">—</option>';return}try{const d=await api('/api/data/datasets/'+id+(requestedSheet?'?sheet='+encodeURIComponent(requestedSheet):''));phase6Datasets=phase6Datasets.map(x=>x.id===d.id?d:x);if(sheet){sheet.innerHTML=(d.sheets||[]).map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');sheet.value=requestedSheet||d.preview?.sheet||d.default_sheet||d.sheets?.[0]||''}phase6RenderPreview(d);await phase6LoadVariables()}catch(e){toast(e.message)}}
function phase6RenderPreview(d){const head=document.getElementById('dataPreviewHead'),body=document.getElementById('dataPreviewRows'),meta=document.getElementById('dataPreviewMeta'),pill=document.getElementById('dataRowsPill');if(!head||!body)return;if(!d?.preview){head.innerHTML='<tr><th>No data</th></tr>';body.innerHTML='<tr><td>Upload an .xlsx or .csv file to begin.</td></tr>';if(meta)meta.textContent='No dataset selected.';if(pill)pill.textContent='0 rows';return}const cols=d.preview.columns||[],rows=d.preview.rows||[];head.innerHTML='<tr><th>#</th>'+cols.map(c=>`<th>${esc(c)}</th>`).join('')+'</tr>';body.innerHTML=rows.length?rows.map(r=>`<tr><td>${r.__row_number__||''}</td>${cols.map(c=>`<td title="${esc(r[c]??'')}">${esc(r[c]??'')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length+1}">No data rows.</td></tr>`;if(meta)meta.textContent=`${d.name} • ${d.preview.sheet||d.default_sheet||''} • Previewing ${rows.length} rows`;if(pill)pill.textContent=`${rows.length}${rows.length>=30?'+':''} rows`;phase6RenderMapping()}
async function phase6LoadVariables(){const rid=document.getElementById('dataRecording')?.value;if(!rid){phase6Variables=[];phase6Mapping=null;phase6RenderMapping();return}try{phase6Variables=await api('/api/data/variables/'+rid);const mappings=await api('/api/data/mappings');const did=document.getElementById('dataDataset')?.value;phase6Mapping=mappings.find(m=>m.recording_id===rid&&(!did||m.dataset_id===did))||null;if(phase6Mapping){document.getElementById('dataResultColumn').value=phase6Mapping.result_column||'WebFlow Result';document.getElementById('dataErrorColumn').value=phase6Mapping.error_column||'WebFlow Error';document.getElementById('dataRunIdColumn').value=phase6Mapping.run_id_column||'WebFlow Run ID'}phase6RenderMapping()}catch(e){toast(e.message)}}
function phase6Columns(){const did=document.getElementById('dataDataset')?.value,d=phase6Datasets.find(x=>x.id===did);return d?.preview?.columns||[]}
function phase6RenderMapping(){const host=document.getElementById('dataMappingRows');if(!host)return;const cols=phase6Columns();if(!phase6Variables.length){host.innerHTML='<div class="placeholder mini">Classify recorded steps as Input, Secret, Assertion, or Output in the Recorder to make them available here.</div>';return}host.innerHTML=phase6Variables.map(v=>{const incoming=['Input','Secret','Assertion'].includes(v.classification),saved=incoming?phase6Mapping?.input_map?.[v.key]:phase6Mapping?.output_map?.[v.key];const options='<option value="">— Not mapped —</option>'+cols.map(c=>`<option value="${esc(c)}" ${c===saved?'selected':''}>${esc(c)}</option>`).join('');const control=incoming?`<select>${options}</select>`:`<input class="output-column-input" value="${esc(saved||v.label||v.key)}" placeholder="Result column name">`;return `<div class="data-map-row ${v.classification==='Secret'?'secret':''}" data-variable="${esc(v.key)}" data-direction="${incoming?'in':'out'}"><div class="data-map-var"><b>${esc(v.key)}</b><small>${esc(v.classification)} • ${esc(v.label)}</small></div><div class="data-map-arrow">${incoming?'←':'→'}</div>${control}</div>`}).join('')}
async function phase6SaveMapping(){const rid=document.getElementById('dataRecording')?.value,did=document.getElementById('dataDataset')?.value,sheet=document.getElementById('dataSheet')?.value;if(!rid||!did){toast('Choose a recording and dataset first');return null}const input_map={},output_map={};document.querySelectorAll('#dataMappingRows [data-variable]').forEach(row=>{const control=row.querySelector('select,input'),val=control?.value?.trim();if(!val)return;(row.dataset.direction==='in'?input_map:output_map)[row.dataset.variable]=val});try{phase6Mapping=await api('/api/data/mappings',{method:'POST',body:JSON.stringify({id:phase6Mapping?.id,recording_id:rid,dataset_id:did,sheet,input_map,output_map,result_column:document.getElementById('dataResultColumn').value,error_column:document.getElementById('dataErrorColumn').value,run_id_column:document.getElementById('dataRunIdColumn').value})});toast('Data mapping saved');return phase6Mapping}catch(e){toast(e.message);return null}}
function phase6ParseRows(text){const set=new Set();String(text||'').split(',').map(x=>x.trim()).filter(Boolean).forEach(part=>{if(part.includes('-')){let [a,b]=part.split('-').map(Number);if(Number.isFinite(a)&&Number.isFinite(b)){if(a>b)[a,b]=[b,a];for(let i=a;i<=b&&i<a+5000;i++)set.add(i)}}else{const n=Number(part);if(Number.isFinite(n))set.add(n)}});return [...set].sort((a,b)=>a-b)}
async function phase6StartBatch(){let mapping=phase6Mapping;if(!mapping)mapping=await phase6SaveMapping();if(!mapping)return;const mode=document.getElementById('batchRowsMode').value,row_numbers=mode==='selected'?phase6ParseRows(document.getElementById('batchRowNumbers').value):[];if(mode==='selected'&&!row_numbers.length){toast('Enter one or more workbook row numbers');return}try{const b=await api('/api/data/batch/start',{method:'POST',body:JSON.stringify({recording_id:mapping.recording_id,dataset_id:mapping.dataset_id,mapping_id:mapping.id,row_numbers,headless:document.getElementById('batchBrowser').value==='true',failure_policy:document.getElementById('batchFailurePolicy').value,retries:1,timeout_ms:12000})});phase6RenderBatch(b);phase6BeginBatchPolling();toast('Data-driven batch started')}catch(e){toast(e.message)}}
function phase6BatchButtons(state){const active=['starting','running','cancelling'].includes(state);const start=document.getElementById('startBatch'),cancel=document.getElementById('cancelBatch'),retry=document.getElementById('retryFailedRows');if(start)start.disabled=active;if(cancel)cancel.disabled=!active;if(retry)retry.disabled=active||!phase6Batch||(phase6Batch.failed_rows||0)<1}
function phase6RenderBatch(b){phase6Batch=b?.id?b:null;const pill=document.getElementById('batchPill'),bar=document.getElementById('batchProgressBar'),txt=document.getElementById('batchProgressText'),rows=document.getElementById('batchRows');if(!pill)return;if(!phase6Batch){pill.textContent='Idle';pill.className='pill draft';bar.style.width='0%';txt.textContent='0 / 0';phase6BatchButtons('idle');return}const state=b.state||'idle',done=(b.completed_rows||0)+(b.failed_rows||0),total=b.total_rows||0,pct=total?Math.round(done/total*100):0;pill.textContent=state[0].toUpperCase()+state.slice(1);pill.className=`pill ${runStatusClass(state)}`;bar.style.width=pct+'%';txt.textContent=`${done} / ${total}`;document.getElementById('batchCurrentRow').textContent=b.current_row||'—';document.getElementById('batchCompleted').textContent=b.completed_rows||0;document.getElementById('batchFailed').textContent=b.failed_rows||0;const result=document.getElementById('batchResult');result.innerHTML=b.result_path?`<a href="${esc(b.result_path)}" download>Download results.xlsx</a>`:'—';rows.innerHTML=(b.rows||[]).length?(b.rows||[]).map(r=>`<tr><td>${r.row_number}</td><td><span class="pill ${r.status==='completed'?'ready':r.status==='failed'?'failed':'testing'}">${esc(r.status)}</span></td><td>${esc(r.run_id||'—')}</td><td title="${esc(JSON.stringify(r.outputs||{}))}">${esc(JSON.stringify(r.outputs||{}))}</td><td title="${esc(r.error||'')}">${esc(r.error||'—')}</td></tr>`).join(''):'<tr><td colspan="5">Preparing rows…</td></tr>';phase6BatchButtons(state)}
function phase6BeginBatchPolling(){clearInterval(phase6BatchPoll);phase6BatchPoll=setInterval(async()=>{try{const b=await api('/api/data/batch/status');phase6RenderBatch(b);if(!['starting','running','cancelling'].includes(b.state)){clearInterval(phase6BatchPoll);phase6BatchPoll=null;phase5LoadRunHistory();loadFlows()}}catch(e){}},700)}
async function phase6CancelBatch(){try{phase6RenderBatch(await api('/api/data/batch/cancel',{method:'POST',body:'{}'}));phase6BeginBatchPolling()}catch(e){toast(e.message)}}
async function phase6RetryFailed(){if(!phase6Batch?.id)return;try{const b=await api(`/api/data/batches/${phase6Batch.id}/retry-failed`,{method:'POST',body:'{}'});phase6RenderBatch(b);phase6BeginBatchPolling();toast('Retrying failed rows only')}catch(e){toast(e.message)}}
document.getElementById('uploadWorkbook')?.addEventListener('click',()=>document.getElementById('dataFileInput').click());document.getElementById('dataFileInput')?.addEventListener('change',phase6Upload);document.getElementById('dataRecording')?.addEventListener('change',phase6LoadVariables);document.getElementById('dataDataset')?.addEventListener('change',e=>phase6LoadDataset(e.target.value));document.getElementById('dataSheet')?.addEventListener('change',e=>phase6LoadDataset(document.getElementById('dataDataset')?.value,e.target.value));document.getElementById('saveDataMapping')?.addEventListener('click',phase6SaveMapping);document.getElementById('batchRowsMode')?.addEventListener('change',e=>document.getElementById('batchRowNumbers').disabled=e.target.value!=='selected');document.getElementById('startBatch')?.addEventListener('click',phase6StartBatch);document.getElementById('cancelBatch')?.addEventListener('click',phase6CancelBatch);document.getElementById('retryFailedRows')?.addEventListener('click',phase6RetryFailed);
phase6LoadSources();api('/api/data/batch/status').then(b=>{if(b?.id){phase6RenderBatch(b);if(['starting','running','cancelling'].includes(b.state))phase6BeginBatchPolling()}}).catch(()=>{});

// ---------- Phase 7: Visual Logic + Governed Python ----------
let designerDoc=null, designerSelected=null, designerSubflowContext=null;
function designerNodeSummary(n){
  if(n.type==='browser') return n.name||'Recorded browser action';
  if(n.type==='if') return n.expression||'condition';
  if(n.type==='foreach') return `${n.item_var||'item'} in ${n.source||'[]'}`;
  if(n.type==='set') return `${n.variable||'value'} = ${n.expression||'None'}`;
  if(n.type==='wait') return `${n.milliseconds||500} ms`;
  if(n.type==='python') return (n.code||'Python code').split('\n')[0];
  if(n.type==='subflow') return n.subflow||'Choose subflow'; return '';
}
function designerIcon(t){return({browser:'●',if:'◇',foreach:'↻',set:'ƒ',wait:'◷',python:'{ }',subflow:'⇢'}[t]||'•')}
async function designerSyncFlowSelect(){
  const sel=document.getElementById('designerFlow');if(!sel)return null;
  designerRecordings=await api('/api/recordings');
  const usable=designerRecordings.filter(r=>r.steps>0 && r.flow_id);
  const currentRecording=sel.dataset.recordingId||usable.find(r=>r.flow_id===activeFlowId)?.id||usable[0]?.id||'';
  sel.innerHTML=usable.length?usable.map(r=>`<option value="${esc(r.flow_id)}" data-recording-id="${esc(r.id)}">${esc(r.recording_name||r.flow_name)} · ${r.steps} steps</option>`).join(''):'<option value="">No saved recordings yet</option>';
  const match=[...sel.options].find(o=>o.dataset.recordingId===currentRecording);if(match)sel.value=match.value;
  activeFlowId=sel.value||null;sel.dataset.recordingId=sel.selectedOptions[0]?.dataset.recordingId||'';return sel.dataset.recordingId||null;
}
async function designerLoad(){
  let rid;try{rid=await designerSyncFlowSelect()}catch(e){toast('Designer: '+e.message);return}
  const fid=document.getElementById('designerFlow')?.value||activeFlowId;if(!fid){designerDoc=null;document.getElementById('designerSteps').innerHTML='<div class="placeholder mini">Record a process first. Your saved recording will appear here automatically.</div>';return}
  try{designerDoc=await api('/api/designs/'+encodeURIComponent(fid));}
  catch(e){
    // First visit to a recording: promote the recorded browser steps directly
    // into Designer instead of showing an empty canvas and requiring a second action.
    try{designerDoc=await api(`/api/designs/${encodeURIComponent(fid)}/import-recording`,{method:'POST',body:JSON.stringify({recording_id:rid})});toast('Recording loaded into Designer')}
    catch(importErr){designerDoc={schema_version:'webflow-flow/1',flow_id:fid,name:'Untitled Flow',steps:[],subflows:{}};toast(importErr.message)}
  }
  designerSelected=null;designerRender();
}
function designerCurrentArray(){if(designerSubflowContext)return designerDoc.subflows?.[designerSubflowContext]||[];return designerDoc?.steps||[]}
function designerRenderNodes(nodes,depth=0){if(!nodes?.length)return depth===0?'<div class="placeholder mini">No designer steps yet. Import a recording or add logic from the toolbox.</div>':'';return nodes.map((n,i)=>{
 const branch=n.type==='if'?`<div class="logic-branch"><div class="branch-label">Then</div>${designerRenderNodes(n.then||[],depth+1)}<div class="branch-label">Else</div>${designerRenderNodes(n.else||[],depth+1)}</div>`:n.type==='foreach'?`<div class="logic-branch"><div class="branch-label">Loop Body</div>${designerRenderNodes(n.body||[],depth+1)}</div>`:'';
 return `<div class="logic-step ${esc(n.type)} ${designerSelected===n.id?'selected':''}" data-design-id="${esc(n.id)}"><div class="type-ico">${esc(designerIcon(n.type))}</div><div><b>${esc(n.name||n.type.toUpperCase())}</b><small>${esc(designerNodeSummary(n))}</small></div><div class="logic-controls"><button data-move="up" title="Move up">↑</button><button data-move="down" title="Move down">↓</button><button data-delete="1" title="Delete">×</button></div></div>${branch}`}).join('')}
function designerRender(){if(!designerDoc)return;const arr=designerCurrentArray();document.getElementById('designerSteps').innerHTML=designerRenderNodes(arr);document.getElementById('designerCount').textContent=`${arr.length} top-level step${arr.length===1?'':'s'}`;document.querySelectorAll('[data-design-id]').forEach(el=>{el.onclick=e=>{const id=el.dataset.designId;if(e.target.dataset.delete){designerDelete(id);return}if(e.target.dataset.move){designerMove(id,e.target.dataset.move);return}designerSelected=id;designerRender();designerInspect(id)}});const subs=designerDoc.subflows||{};document.getElementById('subflowList').innerHTML=Object.keys(subs).length?Object.keys(subs).map(k=>`<button class="subflow-chip" data-subflow="${esc(k)}">⇢ ${esc(k)} · ${subs[k].length} step(s)</button>`).join(''):'<span class="muted" style="font-size:10px">No reusable subflows yet.</span>';document.querySelectorAll('[data-subflow]').forEach(b=>b.onclick=()=>{designerSubflowContext=b.dataset.subflow;designerSelected=null;document.getElementById('designerCount').textContent='Subflow: '+designerSubflowContext;designerRender();});if(!designerSelected)document.getElementById('designerInspector').innerHTML=`<div class="placeholder mini">${designerSubflowContext?'Editing subflow '+esc(designerSubflowContext)+'. Click Home Flow below to return.':'Select a step to configure it.'}</div>${designerSubflowContext?'<button class="btn" id="backMainFlow" style="margin-top:10px">← Home Flow</button>':''}`;document.getElementById('backMainFlow')?.addEventListener('click',()=>{designerSubflowContext=null;designerRender()});}
function designerFind(id,nodes=designerDoc?.steps||[]){for(const n of nodes){if(n.id===id)return n;for(const key of ['then','else','body']){const f=designerFind(id,n[key]||[]);if(f)return f}}for(const a of Object.values(designerDoc?.subflows||{})){for(const n of a){if(n.id===id)return n;for(const key of ['then','else','body']){const f=designerFind(id,n[key]||[]);if(f)return f}}}return null}
function designerFindParent(id,nodes=designerCurrentArray()){for(const n of nodes){for(const key of ['then','else','body']){const a=n[key]||[];const idx=a.findIndex(x=>x.id===id);if(idx>=0)return [a,idx];const nested=designerFindParentNested(id,a);if(nested)return nested}}const idx=nodes.findIndex(x=>x.id===id);return idx>=0?[nodes,idx]:null}
function designerFindParentNested(id,nodes){for(const n of nodes){for(const key of ['then','else','body']){const a=n[key]||[];const idx=a.findIndex(x=>x.id===id);if(idx>=0)return[a,idx];const f=designerFindParentNested(id,a);if(f)return f}}return null}
function designerDelete(id){const p=designerFindParent(id);if(!p)return;p[0].splice(p[1],1);designerSelected=null;designerRender()}
function designerMove(id,dir){const p=designerFindParent(id);if(!p)return;const [a,i]=p,j=dir==='up'?i-1:i+1;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];designerRender()}
function designerAdd(type){if(!designerDoc)return;const id=crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random());const base={id,type,enabled:true,name:({if:'IF / ELSE',foreach:'For Each',set:'Set Variable',wait:'Wait',python:'Python Extension',subflow:'Call Subflow'}[type]||type)};if(type==='if'){base.expression='status == "Ready"';base.then=[];base.else=[]}if(type==='foreach'){base.source='items';base.item_var='item';base.index_var='index';base.body=[]}if(type==='set'){base.variable='value';base.expression='None'}if(type==='wait')base.milliseconds=500;if(type==='python')base.code='# Use variables from Data & Variables or earlier Set/Output steps.\n# Example: variables["normalized"] = str(variables.get("value", "")).strip().upper()\nresult = variables.get("normalized", "")';if(type==='subflow')base.subflow=Object.keys(designerDoc.subflows||{})[0]||'';designerCurrentArray().push(base);designerSelected=id;designerRender();designerInspect(id)}
function designerInspect(id){const n=designerFind(id);if(!n)return;let fields=`<div class="field"><label>Step Name</label><input id="diName" value="${esc(n.name||'')}"></div><div class="field"><label>Enabled</label><select id="diEnabled"><option value="true" ${n.enabled!==false?'selected':''}>Yes</option><option value="false" ${n.enabled===false?'selected':''}>No</option></select></div>`;
 if(n.type==='browser')fields+=`<div class="field"><label>Source</label><input value="${esc(n.source_recording_id||'')} / ${esc(n.source_step_id||'')}" readonly></div><div class="designer-code-warning">Browser steps stay linked to recorder/object metadata. Edit the target in Object Repository rather than duplicating selectors here.</div>`;
 if(n.type==='if')fields+=`<div class="field"><label>Condition Expression</label><input id="diExpression" value="${esc(n.expression||'')}"></div><div class="designer-code-warning">Examples: <b>status == "Ready"</b>, <b>amount &gt; 100</b>, <b>document_id in allowed_docs</b>.</div>`;
 if(n.type==='foreach')fields+=`<div class="field"><label>Iterable Expression</label><input id="diSource" value="${esc(n.source||'')}"></div><div class="field"><label>Item Variable</label><input id="diItem" value="${esc(n.item_var||'item')}"></div><div class="field"><label>Index Variable</label><input id="diIndex" value="${esc(n.index_var||'index')}"></div>`;
 if(n.type==='set')fields+=`<div class="field"><label>Variable</label><input id="diVar" value="${esc(n.variable||'value')}"></div><div class="field"><label>Expression</label><input id="diExpression" value="${esc(n.expression||'None')}"></div>`;
 if(n.type==='wait')fields+=`<div class="field"><label>Milliseconds</label><input id="diMs" type="number" min="0" max="60000" value="${esc(n.milliseconds||500)}"></div>`;
 if(n.type==='python')fields+=`<div class="field"><label>Governed Python</label><textarea id="diCode">${esc(n.code||'')}</textarea></div><div class="designer-code-warning"><b>When to use Python:</b> transform values or calculate something that is awkward visually. Read/write <code>variables</code>, read captured <code>outputs</code>, and assign <code>result</code> to show a node result. Imports, files, network access, functions/classes and private attributes are blocked. Example: <code>variables['clean_id']=str(variables.get('document_id','')).strip()</code>.</div>`;
 if(n.type==='subflow')fields+=`<div class="field"><label>Subflow</label><select id="diSubflow">${Object.keys(designerDoc.subflows||{}).map(k=>`<option ${k===n.subflow?'selected':''}>${esc(k)}</option>`).join('')}</select></div>`;
 fields+=`<button class="btn blue" id="applyInspector">Apply Changes</button>`;document.getElementById('designerInspector').innerHTML=fields;document.getElementById('applyInspector').onclick=()=>{n.name=document.getElementById('diName').value;n.enabled=document.getElementById('diEnabled').value==='true';if(n.type==='if'||n.type==='set')n.expression=document.getElementById('diExpression').value;if(n.type==='foreach'){n.source=document.getElementById('diSource').value;n.item_var=document.getElementById('diItem').value;n.index_var=document.getElementById('diIndex').value}if(n.type==='set')n.variable=document.getElementById('diVar').value;if(n.type==='wait')n.milliseconds=Number(document.getElementById('diMs').value||500);if(n.type==='python')n.code=document.getElementById('diCode').value;if(n.type==='subflow')n.subflow=document.getElementById('diSubflow').value;designerRender();designerInspect(id);toast('Step updated')};}
async function designerSave(){if(!designerDoc)return;try{designerDoc=await api('/api/designs/'+encodeURIComponent(designerDoc.flow_id),{method:'PUT',body:JSON.stringify({name:designerDoc.name,steps:designerDoc.steps,subflows:designerDoc.subflows})});toast('Designer flow saved')}catch(e){toast(e.message)}}
async function designerImport(){const sel=document.getElementById('designerFlow'),fid=sel.value,rid=sel.selectedOptions[0]?.dataset.recordingId||'';try{designerDoc=await api(`/api/designs/${encodeURIComponent(fid)}/import-recording`,{method:'POST',body:JSON.stringify({recording_id:rid})});designerSubflowContext=null;designerSelected=null;designerRender();toast('Recorded steps imported')}catch(e){toast(e.message)}}
function designerNewSubflow(){let name=prompt('Subflow name','Login');if(!name)return;name=name.trim();if(!name)return;designerDoc.subflows=designerDoc.subflows||{};if(designerDoc.subflows[name]){toast('That subflow already exists');return}designerDoc.subflows[name]=[];designerSubflowContext=name;designerRender();toast('Subflow created')}
document.querySelectorAll('[data-add-node]').forEach(b=>b.addEventListener('click',()=>designerAdd(b.dataset.addNode)));document.getElementById('designerFlow')?.addEventListener('change',e=>{activeFlowId=e.target.value;e.target.dataset.recordingId=e.target.selectedOptions[0]?.dataset.recordingId||'';designerSubflowContext=null;designerLoad()});document.getElementById('saveDesign')?.addEventListener('click',designerSave);document.getElementById('importRecordingDesign')?.addEventListener('click',designerImport);document.getElementById('newSubflow')?.addEventListener('click',designerNewSubflow);

// ---------- Phase 8: Script Export / Import ----------
let phase8Script=null;
function scriptModeLabel(mode){return({
  'visual-managed':'Visual Managed ✓',
  'code-managed-compatible':'Code Managed · Compatible',
  'code-managed-drifted':'Code Managed · Visual Drift',
  'code-managed-unlinked':'Code Managed · Unlinked',
  'invalid':'Invalid Script'
}[mode]||mode||'Unknown')}
function scriptModeClass(mode){if(mode==='visual-managed')return'ready';if(mode==='code-managed-compatible')return'testing';if(mode==='code-managed-drifted'||mode==='code-managed-unlinked')return'draft';return'failed'}
function phase8SyncFlow(){const s=document.getElementById('scriptFlow');if(!s)return;const cur=s.value||activeFlowId||flows[0]?.id||'';s.innerHTML=flows.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('');if(flows.some(f=>f.id===cur))s.value=cur;}
async function phase8LoadScript(){phase8SyncFlow();const fid=document.getElementById('scriptFlow')?.value;if(!fid)return;try{phase8Script=await api('/api/scripts/'+encodeURIComponent(fid));phase8RenderScript()}catch(e){phase8Script=null;document.getElementById('scriptCode').textContent='# '+e.message;toast(e.message)}}
function phase8RenderScript(){const d=phase8Script||{};const f=flows.find(x=>x.id===d.flow_id)||{};document.getElementById('scriptTitle').textContent=(f.name||'WebFlow Automation')+' · automation.py';document.getElementById('scriptCode').textContent=d.source||'# No generated source';const mode=d.mode||'visual-managed',pill=document.getElementById('scriptModePill');pill.textContent=scriptModeLabel(mode);pill.className='pill '+scriptModeClass(mode);const v=d.validation||{};const vp=document.getElementById('scriptValidationPill');vp.textContent=v.ok?'Syntax valid':'Needs validation';vp.className='pill '+(v.ok?'ready':'draft');document.getElementById('scriptMeta').textContent=`${d.designer_steps||0} top-level Designer step(s) · ${d.persisted?'Saved script state':'Generated preview'}`;document.getElementById('scriptStateText').textContent=d.drift?'The visual flow changed after this script was saved. Regenerate to return to Visual Managed, or keep the custom code as Code Managed.':'The script is aligned with the current visual design hash.';let msg='';if(mode==='visual-managed')msg='<div class="mode-card"><b>Visual Managed</b><br>The source exactly matches code generated from the current visual flow. Regeneration is safe.</div>';else if(mode==='code-managed-compatible')msg='<div class="mode-card warn"><b>Code Managed · Compatible</b><br>Custom edits were detected, but the embedded manifest still points to the current visual design.</div>';else if(mode==='code-managed-drifted')msg='<div class="mode-card warn"><b>Visual Drift Detected</b><br>The uploaded code references an older design hash. WebFlow will not pretend the visual canvas represents these custom edits.</div>';else msg='<div class="mode-card warn"><b>Code Managed · Unlinked</b><br>This is valid Python but does not carry a matching WebFlow manifest marker.</div>';document.getElementById('scriptInspector').innerHTML=`${msg}<div class="field"><label>Validation</label><input value="${esc(v.message||'Not yet validated')}" readonly></div><div class="field"><label>Current Visual Hash</label><div class="hash">${esc(d.current_design_hash||d.design_hash||'—')}</div></div><div class="field"><label>Script-linked Hash</label><div class="hash">${esc(d.design_hash||d.manifest?.design_hash||'—')}</div></div><div class="field"><label>Source SHA-256</label><div class="hash">${esc(d.source_hash||d.generated_source_hash||'—')}</div></div><div class="field"><label>Management Rule</label><div style="font-size:9px;line-height:1.5;color:#66798d">Editing exported Python never silently rewrites the visual canvas. Re-uploaded custom code is tracked explicitly as Code Managed unless it exactly matches regenerated source.</div></div>`;}
async function phase8Regenerate(){const fid=document.getElementById('scriptFlow')?.value;if(!fid)return;if(phase8Script?.mode&&phase8Script.mode!=='visual-managed'&&!confirm('Regenerating will replace the saved custom script with code from the current visual flow. Continue?'))return;try{phase8Script=await api(`/api/scripts/${encodeURIComponent(fid)}/regenerate`,{method:'POST',body:'{}'});phase8RenderScript();toast('Script regenerated from visual flow')}catch(e){toast(e.message)}}
async function phase8Validate(){const fid=document.getElementById('scriptFlow')?.value;if(!fid)return;try{phase8Script=await api(`/api/scripts/${encodeURIComponent(fid)}/validate`,{method:'POST',body:'{}'});phase8RenderScript();toast(phase8Script.validation?.message||'Validated')}catch(e){toast(e.message)}}
function phase8Download(){const fid=document.getElementById('scriptFlow')?.value;if(!fid)return;window.location.href=`/api/scripts/${encodeURIComponent(fid)}/download`}
function phase8UploadClick(){document.getElementById('scriptUploadInput')?.click()}
async function phase8UploadFile(file){if(!file)return;const fid=document.getElementById('scriptFlow')?.value;if(!fid)return;const buf=await file.arrayBuffer(),bytes=new Uint8Array(buf);let bin='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk)bin+=String.fromCharCode(...bytes.subarray(i,i+chunk));const b64=btoa(bin);try{const r=await api(`/api/scripts/${encodeURIComponent(fid)}/import`,{method:'POST',body:JSON.stringify({name:file.name,content_base64:b64})});phase8Script=r;phase8RenderScript();toast('Modified script imported and classified')}catch(e){toast(e.message)}}
document.getElementById('scriptFlow')?.addEventListener('change',phase8LoadScript);document.getElementById('scriptRegenerateBtn')?.addEventListener('click',phase8Regenerate);document.getElementById('scriptValidateBtn')?.addEventListener('click',phase8Validate);document.getElementById('scriptDownloadBtn')?.addEventListener('click',phase8Download);document.getElementById('scriptUploadBtn')?.addEventListener('click',phase8UploadClick);document.getElementById('scriptUploadInput')?.addEventListener('change',e=>{phase8UploadFile(e.target.files?.[0]);e.target.value=''});


// ---------- Phase 9: Performance & Synthetic Monitoring ----------
let phase9Poll=null, phase9Current=null;
function phase9SyncFlow(){const s=document.getElementById('perfFlow');if(!s)return;const cur=s.value||activeFlowId||flows.find(f=>f.recording_id)?.id||flows[0]?.id||'';s.innerHTML=flows.map(f=>`<option value="${esc(f.id)}" ${f.recording_id?'':'disabled'}>${esc(f.name)}${f.recording_id?'':' · no recording'}</option>`).join('');if(flows.some(f=>f.id===cur&&f.recording_id))s.value=cur;else{const first=flows.find(f=>f.recording_id);if(first)s.value=first.id;}}
function perfMs(v){if(v==null||Number.isNaN(Number(v)))return'—';const n=Number(v);return n>=1000?`${(n/1000).toFixed(n>=10000?1:2)}s`:`${Math.round(n)}ms`}
function perfStateClass(s){return s==='completed'?'ready':s==='failed'?'failed':s==='cancelled'?'draft':'testing'}
function phase9Render(t){phase9Current=t||{};const state=t?.state||'idle',pill=document.getElementById('perfState');if(pill){pill.textContent=state.replace(/^./,c=>c.toUpperCase());pill.className='pill '+perfStateClass(state)}const total=Number(t?.total_executions||0),done=Number(t?.completed_executions||0),pct=total?Math.min(100,Math.round(done/total*100)):0;document.getElementById('perfProgressBar').style.width=pct+'%';document.getElementById('perfProgressText').textContent=`${done} / ${total}`;document.getElementById('perfMessage').textContent=t?.current_message||'Select a recorded flow and start a synthetic test.';document.getElementById('perfStart').disabled=['starting','running','cancelling'].includes(state);document.getElementById('perfCancel').disabled=!['starting','running','cancelling'].includes(state);
 const m=t?.metrics||{};document.getElementById('perfStatRuns').textContent=m.count??0;document.getElementById('perfStatAvg').textContent=perfMs(m.average_ms);document.getElementById('perfStatMedian').textContent=perfMs(m.median_ms);document.getElementById('perfStatP95').textContent=perfMs(m.p95_ms);document.getElementById('perfStatP99').textContent=perfMs(m.p99_ms);document.getElementById('perfStatFailures').textContent=m.failures??0;
 const samples=t?.samples||[],chart=document.getElementById('perfChart');if(!samples.length)chart.innerHTML='<div class="placeholder mini">No performance samples yet.</div>';else{const vals=samples.map(x=>Number(x.duration_ms||0)),max=Math.max(1,...vals);chart.innerHTML=samples.map(x=>{const h=Math.max(4,Math.round(Number(x.duration_ms||0)/max*100));return `<button class="perf-bar ${x.state==='completed'?'':'bad'}" style="height:${h}%" title="Run ${x.sample_no}: ${perfMs(x.duration_ms)} · ${esc(x.state)}" data-run-id="${esc(x.run_id||'')}"><span>${x.sample_no}</span></button>`}).join('');chart.querySelectorAll('[data-run-id]').forEach(b=>b.onclick=()=>{if(b.dataset.runId){go('runs');api('/api/runs/'+encodeURIComponent(b.dataset.runId)).then(r=>{phase5SelectedStepId=null;phase5RenderRun(r)}).catch(e=>toast(e.message))}})}
 const steps=t?.step_metrics||[],rows=document.getElementById('perfStepRows');rows.innerHTML=steps.length?steps.map(x=>`<tr><td>${esc(x.sequence??'—')}</td><td><b>${esc(x.label||'Step')}</b></td><td>${esc(x.action||'')}</td><td>${x.count||0}</td><td>${perfMs(x.average_ms)}</td><td>${perfMs(x.median_ms)}</td><td>${perfMs(x.p95_ms)}</td><td>${perfMs(x.min_ms)}</td><td>${perfMs(x.max_ms)}</td><td><span class="pill ${x.failures?'failed':'ready'}">${x.failures||0}</span></td></tr>`).join(''):'<tr><td colspan="10">No measured steps yet.</td></tr>';
 const ce=t?.console_errors||[],ne=t?.network_errors||[];document.getElementById('perfConsoleCount').textContent=ce.length;document.getElementById('perfNetworkCount').textContent=ne.length;const diag=[...ce.map(x=>({...x,_kind:'Console'})),...ne.map(x=>({...x,_kind:'Network'}))].slice(-60).reverse();document.getElementById('perfDiagList').innerHTML=diag.length?diag.map(x=>`<div class="perf-diag-item"><span class="pill ${x._kind==='Console'?'draft':'testing'}">${x._kind}</span><div><b>Run ${esc(x.sample_no||'—')} · ${esc(x.type||'error')}${x.status?' · HTTP '+x.status:''}</b><small>${esc(x.text||x.detail||x.url||'')}</small>${x.url&&(x.text||x.detail)?`<code>${esc(x.url)}</code>`:''}</div></div>`).join(''):'<div class="placeholder mini">No browser diagnostics captured.</div>';
}
async function phase9History(){try{const h=await api('/api/performance/tests'),rows=document.getElementById('perfHistoryRows');rows.innerHTML=h.length?h.map(t=>{const f=flows.find(x=>x.id===t.flow_id)||{};const m=t.metrics||{};return `<tr data-perf-id="${esc(t.id)}"><td>${esc(t.started_at?new Date(t.started_at).toLocaleString():'—')}</td><td><span class="pill ${perfStateClass(t.state)}">${esc(t.state||'')}</span></td><td><b>${esc(f.name||t.flow_id||'—')}</b></td><td>${m.count??t.completed_samples??0}</td><td>${t.concurrency||1}</td><td>${perfMs(m.average_ms)}</td><td>${perfMs(m.p95_ms)}</td><td>${m.success_rate==null?'—':m.success_rate+'%'}</td></tr>`}).join(''):'<tr><td colspan="8">No performance history yet.</td></tr>';rows.querySelectorAll('[data-perf-id]').forEach(r=>r.onclick=async()=>{try{const t=await api('/api/performance/tests/'+encodeURIComponent(r.dataset.perfId));phase9Render(t)}catch(e){toast(e.message)}})}catch(e){console.warn(e)}}
async function phase9Load(){phase9SyncFlow();try{const t=await api('/api/performance/status');phase9Render(t);if(['starting','running','cancelling'].includes(t.state))phase9BeginPoll()}catch(e){console.warn(e)}phase9History()}
function phase9BeginPoll(){clearInterval(phase9Poll);phase9Poll=setInterval(async()=>{try{const t=await api('/api/performance/status');phase9Render(t);if(!['starting','running','cancelling'].includes(t.state)){clearInterval(phase9Poll);phase9Poll=null;phase9History();loadFlows()}}catch(e){}},700)}
async function phase9Start(){const flow_id=document.getElementById('perfFlow').value;if(!flow_id){toast('Select a recorded flow');return}const body={flow_id,runs:Number(document.getElementById('perfRuns').value),warmups:Number(document.getElementById('perfWarmups').value),concurrency:Number(document.getElementById('perfConcurrency').value),headless:document.getElementById('perfHeadless').value==='true',timeout_ms:Number(document.getElementById('perfTimeout').value),retries:Number(document.getElementById('perfRetries').value),use_designer:true};try{const t=await api('/api/performance/start',{method:'POST',body:JSON.stringify(body)});phase9Render(t);phase9BeginPoll();toast('Performance test started')}catch(e){toast(e.message)}}
async function phase9Cancel(){try{const t=await api('/api/performance/cancel',{method:'POST',body:'{}'});phase9Render(t);toast('Cancelling performance test…')}catch(e){toast(e.message)}}
document.getElementById('perfStart')?.addEventListener('click',phase9Start);document.getElementById('perfCancel')?.addEventListener('click',phase9Cancel);document.getElementById('perfRefresh')?.addEventListener('click',phase9History);document.getElementById('perfFlow')?.addEventListener('change',e=>{activeFlowId=e.target.value});



// ---------- Phase 10: Scheduling / Worker Model ----------
let phase10Poll=null;
function phase10StateClass(s){if(s==='completed')return'ready';if(s==='failed')return'failed';if(['running','assigned','cancelling'].includes(s))return'testing';return'draft'}
function phase10FlowName(id){return flows.find(f=>f.id===id)?.name||id||'—'}
function phase10Date(v){if(!v)return'—';try{return new Date(v).toLocaleString()}catch(e){return v}}
function phase10Cadence(s){if(s.kind==='once')return `Once · ${phase10Date(s.run_at)}`;if(s.kind==='daily')return `Daily · ${esc(s.daily_time||'08:00')} UTC`;return `Every ${Number(s.interval_minutes||60)} min`}
async function phase10Status(){try{const st=await api('/api/worker/status');const pill=document.getElementById('workerAdapterPill');if(pill){pill.textContent=st.adapter||'worker';pill.className='pill ready'}document.getElementById('workerActive').textContent=`${st.active_workers||0} / ${st.max_workers||0}`;document.getElementById('workerQueued').textContent=st.queue_depth||0;document.getElementById('workerSchedules').textContent=st.schedules_enabled||0;document.getElementById('workerRetention').textContent=`${st.settings?.retention_days||'—'} days`;return st}catch(e){const p=document.getElementById('workerAdapterPill');if(p){p.textContent='Worker Offline';p.className='pill failed'}return null}}
async function phase10Jobs(){try{const jobs=await api('/api/worker/jobs?limit=100'),rows=document.getElementById('queueRows');if(!rows)return jobs;rows.innerHTML=jobs.length?jobs.map(j=>`<tr ${j.run_id?`data-run-id="${esc(j.run_id)}"`:''}><td>${esc(phase10Date(j.created_at))}</td><td><b>${esc(phase10FlowName(j.flow_id))}</b><small class="worker-message">${esc(j.message||'')}</small></td><td><span class="worker-source">${esc(j.source||'manual')}</span></td><td><span class="pill ${phase10StateClass(j.state)}">${esc(j.state||'')}</span></td><td>${esc(j.worker_id||'—')}</td><td>${j.run_id?`<code>${esc(j.run_id.slice(0,8))}</code>`:'—'}</td><td>${fmtMs(j.duration_ms)}</td><td><div class="queue-actions">${['queued','assigned','running','cancelling'].includes(j.state)?`<button class="btn" data-cancel-job="${esc(j.id)}">Cancel</button>`:''}${['failed','cancelled'].includes(j.state)?`<button class="btn" data-retry-job="${esc(j.id)}">Retry</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="8">Queue is empty.</td></tr>';rows.querySelectorAll('tr[data-run-id]').forEach(tr=>tr.ondblclick=async()=>{try{const r=await api('/api/runs/'+encodeURIComponent(tr.dataset.runId));phase5SelectedStepId=null;phase5RenderRun(r);document.querySelector('.content').scrollTop=0}catch(e){toast(e.message)}});rows.querySelectorAll('[data-cancel-job]').forEach(b=>b.onclick=async e=>{e.stopPropagation();try{await api(`/api/worker/jobs/${b.dataset.cancelJob}/cancel`,{method:'POST',body:'{}'});toast('Queue job cancellation requested');phase10Load()}catch(err){toast(err.message)}});rows.querySelectorAll('[data-retry-job]').forEach(b=>b.onclick=async e=>{e.stopPropagation();try{await api(`/api/worker/jobs/${b.dataset.retryJob}/retry`,{method:'POST',body:'{}'});toast('Job re-queued');phase10Load()}catch(err){toast(err.message)}});return jobs}catch(e){console.warn(e);return[]}}
async function phase10Schedules(){try{const list=await api('/api/schedules'),rows=document.getElementById('scheduleRows');if(!rows)return list;rows.innerHTML=list.length?list.map(x=>`<tr><td><b>${esc(x.name||'Schedule')}</b></td><td>${esc(phase10FlowName(x.flow_id))}</td><td class="schedule-cadence"><b>${phase10Cadence(x)}</b><small>${x.headless?'Headless':'Headed'} · ${x.retries||0} retries</small></td><td>${esc(phase10Date(x.next_run_at))}</td><td>${esc(phase10Date(x.last_enqueued_at))}</td><td><span class="pill ${x.enabled?'ready':'draft'}">${x.enabled?'Enabled':'Disabled'}</span></td><td><div class="schedule-actions"><button class="btn" data-toggle-schedule="${esc(x.id)}" data-enabled="${x.enabled?'1':'0'}">${x.enabled?'Disable':'Enable'}</button><button class="btn" data-delete-schedule="${esc(x.id)}">Delete</button></div></td></tr>`).join(''):'<tr><td colspan="7">No schedules yet.</td></tr>';rows.querySelectorAll('[data-toggle-schedule]').forEach(b=>b.onclick=async()=>{try{await api(`/api/schedules/${b.dataset.toggleSchedule}/toggle`,{method:'POST',body:JSON.stringify({enabled:b.dataset.enabled!=='1'})});phase10Load();toast('Schedule updated')}catch(e){toast(e.message)}});rows.querySelectorAll('[data-delete-schedule]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this schedule?'))return;try{await api(`/api/schedules/${b.dataset.deleteSchedule}`,{method:'DELETE'});phase10Load();toast('Schedule deleted')}catch(e){toast(e.message)}});return list}catch(e){console.warn(e);return[]}}
async function phase10Load(){await Promise.all([phase10Status(),phase10Jobs(),phase10Schedules()]);const st=await phase10Status();clearInterval(phase10Poll);if(st&&(st.active_workers||st.queue_depth)){phase10Poll=setInterval(async()=>{const latest=await phase10Status();await phase10Jobs();if(!(latest?.active_workers||latest?.queue_depth)){clearInterval(phase10Poll);phase10Poll=null;phase5LoadRunHistory();loadFlows()}},1800)}}
async function phase10QueueRun(){const sel=document.getElementById('runRecording');if(!sel?.value){toast('Record and save a process first');return}const opt=sel.selectedOptions[0],payload={recording_id:sel.value,flow_id:opt?.dataset.flow||'',headless:document.getElementById('runBrowser').value==='true',timeout_ms:Number(document.getElementById('runTimeout').value),retries:Number(document.getElementById('runRetries').value),failure_policy:document.getElementById('runFailurePolicy').value,use_designer:true,source:'manual',client_id:document.getElementById('runClientSelect')?.value||''};try{await governedMutation('/api/worker/enqueue',payload,'Confirm queued execution?');toast('Automation added to worker queue');phase10Load()}catch(e){if(!e.cancelled)toast(e.message)}}
function phase10ScheduleMode(){const k=document.getElementById('scheduleKind')?.value;const a=document.getElementById('scheduleIntervalField'),d=document.getElementById('scheduleDailyField'),o=document.getElementById('scheduleOnceField');if(a)a.hidden=k!=='interval';if(d)d.hidden=k!=='daily';if(o)o.hidden=k!=='once'}
async function phase10CreateSchedule(){const sel=document.getElementById('runRecording');if(!sel?.value){toast('Choose a recorded flow in Run Configuration first');return}const opt=sel.selectedOptions[0],kind=document.getElementById('scheduleKind').value,once=document.getElementById('scheduleOnce').value;let run_at=null;if(kind==='once'){if(!once){toast('Choose a run date/time');return}run_at=new Date(once).toISOString()}const body={name:document.getElementById('scheduleName').value.trim()||`${opt?.textContent?.split(' • ')[0]||'WebFlow'} schedule`,flow_id:opt?.dataset.flow||'',recording_id:sel.value,enabled:true,kind,interval_minutes:Number(document.getElementById('scheduleInterval').value||60),daily_time:document.getElementById('scheduleDaily').value||'12:00',run_at,headless:document.getElementById('scheduleHeadless').value==='true',timeout_ms:Number(document.getElementById('runTimeout').value),retries:Number(document.getElementById('runRetries').value),failure_policy:document.getElementById('runFailurePolicy').value,use_designer:true,client_id:document.getElementById('runClientSelect')?.value||''};try{await governedMutation('/api/schedules',body,'Approve this schedule?');document.getElementById('scheduleName').value='';toast('Schedule created');phase10Load()}catch(e){if(!e.cancelled)toast(e.message)}}
async function phase10LoadSettings(){try{const st=await api('/api/worker/status'),x=st.settings||{};document.getElementById('workerSettingsAdapter').textContent=x.adapter||st.adapter||'local-thread-pool';document.getElementById('workerMax').value=String(x.max_workers||2);document.getElementById('workerQueueLimit').value=x.queue_limit||100;document.getElementById('workerRetentionDays').value=String(x.retention_days||14)}catch(e){toast(e.message)}}
async function phase10SaveSettings(){try{await api('/api/worker/settings',{method:'PUT',body:JSON.stringify({max_workers:Number(document.getElementById('workerMax').value),queue_limit:Number(document.getElementById('workerQueueLimit').value),retention_days:Number(document.getElementById('workerRetentionDays').value)})});toast('Worker settings saved');phase10LoadSettings();phase10Status()}catch(e){toast(e.message)}}
async function phase10Cleanup(){try{const r=await api('/api/worker/cleanup',{method:'POST',body:'{}'});toast(`Removed ${r.removed_jobs||0} retained queue jobs`);phase10Load()}catch(e){toast(e.message)}}
document.getElementById('queueAutomation')?.addEventListener('click',phase10QueueRun);document.getElementById('refreshQueue')?.addEventListener('click',phase10Load);document.getElementById('refreshSchedules')?.addEventListener('click',phase10Load);document.getElementById('scheduleKind')?.addEventListener('change',phase10ScheduleMode);document.getElementById('saveSchedule')?.addEventListener('click',phase10CreateSchedule);document.getElementById('saveWorkerSettings')?.addEventListener('click',phase10SaveSettings);document.getElementById('cleanupWorkerHistory')?.addEventListener('click',phase10Cleanup);phase10ScheduleMode();



// ---------- Phase 11: ALM Hub / SAP BTP Plug-in ----------
async function phase11LoadSession(){
  try{
    const s=await api('/api/session');
    const name=document.getElementById('sessionName'),source=document.getElementById('sessionSource'),avatar=document.getElementById('sessionAvatar');
    if(name)name.textContent=s.display_name||s.user_name||'WebFlow User';
    if(source)source.textContent=(s.roles||[]).length?`${s.source||'runtime'} · ${(s.roles||[]).join(', ')}`:(s.source||'runtime');
    if(avatar){const parts=String(s.display_name||s.user_name||'WF').trim().split(/\s+/).filter(Boolean);avatar.textContent=(parts.length>1?(parts[0][0]+parts[parts.length-1][0]):String(parts[0]||'WF').slice(0,2)).toUpperCase();}
  }catch(e){console.warn('Session metadata unavailable',e)}
}
function phase11StatusClass(v){return v==='ready'?'ready':v==='warning'?'failed':v==='local'?'draft':'testing'}
async function phase11LoadRuntime(){
  try{
    const [rt,ready,hub]=await Promise.all([api('/api/runtime'),api('/api/btp/readiness'),api('/api/hub/plugin')]);
    const p=rt.profile||{},st=rt.storage||{};
    const env=document.getElementById('runtimeEnvironment'),route=document.getElementById('runtimeRoute'),auth=document.getElementById('runtimeAuth'),storage=document.getElementById('runtimeStorage'),pill=document.getElementById('runtimeEnvPill');
    if(env)env.value=p.environment||'local';if(route)route.value=p.public_url||'Standalone / local route';if(auth)auth.value=p.auth_adapter||'local-development';if(storage)storage.value=st.adapter||'local-json';
    if(pill){pill.textContent=p.cloud_foundry?'SAP BTP / Cloud Foundry':'Standalone';pill.className='pill '+(p.cloud_foundry?'ready':'draft')}
    const rp=document.getElementById('btpReadinessPill');if(rp){rp.textContent=ready.ready?'Ready':'Attention';rp.className='pill '+(ready.ready?'ready':'testing')}
    const checks=document.getElementById('btpReadinessChecks');if(checks){checks.innerHTML=(ready.checks||[]).map(c=>`<div class="runtime-check"><span class="pill ${phase11StatusClass(c.status)}">${esc(c.status)}</span><div><b>${esc(c.label)}</b><small>${esc(c.detail||'')}</small></div></div>`).join('')||'<div class="placeholder mini">No readiness checks returned.</div>'}
    const hs=document.getElementById('hubSection'),hl=document.getElementById('hubLaunchMode'),he=document.getElementById('hubEngenie');if(hs)hs.value=hub.section||'SRE Workbench';if(hl)hl.value=hub.launch_mode||'embedded-or-fullscreen';if(he)he.value=hub.engenie_manifest_path||'/api/engenie/manifest';
  }catch(e){toast('Runtime readiness: '+e.message)}
}
async function downloadLocalClient(){
  const btn=document.getElementById('downloadLocalClient');
  try{
    if(btn){btn.disabled=true;btn.textContent='Preparing…'}
    const response=await fetch(webflowUrl('/api/hybrid/client-download'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_name:'WebFlow Local Client'})});
    if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.message||data.error||`HTTP ${response.status}`)}
    const blob=await response.blob();const cd=response.headers.get('Content-Disposition')||'';const match=cd.match(/filename="?([^";]+)"?/i);const name=match?.[1]||'ALM-WebFlow-Local-Client.zip';
    const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
    toast('Local Client download ready — extract it and run WebFlowLocalClient.exe');
  }catch(e){toast(e.message)}finally{if(btn){btn.disabled=false;btn.textContent='Download Local Client'}}
}
