// ---------- Phase 12 + 13: governed Engenie bridge + external AI adapters ----------
// The chat UI stays the same regardless of provider. Phase 13 only changes the
// interpretation layer; all actual WebFlow operations still pass through the
// Phase 12 governed endpoints and execution queue.
let phase12PendingInvocation=null;
let phase13Providers=[];
function phase12OpenEngenie(){const p=document.getElementById('engeniePanel'),b=document.getElementById('engenieBackdrop');if(!p)return;p.classList.add('open');p.setAttribute('aria-hidden','false');if(b)b.hidden=false;phase13LoadProviders();setTimeout(()=>document.getElementById('engenieInput')?.focus(),80)}
function phase12CloseEngenie(){const p=document.getElementById('engeniePanel'),b=document.getElementById('engenieBackdrop');if(p){p.classList.remove('open');p.setAttribute('aria-hidden','true')}if(b)b.hidden=true}
function phase12Msg(who,text,extra=''){const box=document.getElementById('engenieMessages');if(!box)return;const d=document.createElement('div');d.className='engenie-msg '+(who==='You'?'user':'bot');d.innerHTML=`<b>${esc(who)}</b><p>${esc(text)}</p>${extra}`;box.appendChild(d);box.scrollTop=box.scrollHeight;return d}
function phase12FlowCards(items=[]){return items.slice(0,8).map(f=>`<div class="engenie-flow-card"><b>${esc(f.name)}</b><small>${esc(f.description||'')} · ${f.runnable?'Runnable':'Needs recording'}${f.destructive?' · Confirmation required':''}</small></div>`).join('')}
function phase13ProviderClass(p){return p.configured&&p.enabled?'ready':p.enabled?'testing':'draft'}
function phase13ProviderOptions(items=[]){return items.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}${p.configured?'':' · not configured'}</option>`).join('')}
async function phase13LoadProviders(){
  try{
    const r=await api('/api/ai/providers');phase13Providers=r.providers||[];
    const configured=phase13Providers.filter(p=>p.configured&&p.enabled).length;
    const summary=document.getElementById('aiProviderSummary');if(summary){summary.textContent=`${configured} configured / ${phase13Providers.length}`;summary.className='pill '+(configured?'ready':'testing')}
    const list=document.getElementById('aiProviderList');if(list)list.innerHTML=phase13Providers.map(p=>`<div class="ai-provider-row"><span class="pill ${phase13ProviderClass(p)}">${p.configured?'Ready':'Needs config'}</span><div><b>${esc(p.name)}${p.default?' · Default':''}</b><small>${esc(p.adapter||'')} · ${esc(p.model||'model from gateway')}</small><small>${esc(p.description||'')}</small></div><code>${esc(p.secret_env||'no secret required')}</code></div>`).join('')||'<div class="placeholder mini">No provider adapters configured.</div>';
    const opts=phase13ProviderOptions(phase13Providers);const test=document.getElementById('aiProviderTestSelect'),chat=document.getElementById('engenieProvider');
    if(test){const old=test.value;test.innerHTML=opts;test.value=phase13Providers.some(x=>x.id===old)?old:(r.default_provider||'local')}
    if(chat){const old=chat.value;chat.innerHTML=opts;chat.value=phase13Providers.some(x=>x.id===old)?old:(r.default_provider||'local')}
    return r;
  }catch(e){const summary=document.getElementById('aiProviderSummary');if(summary){summary.textContent='Provider registry offline';summary.className='pill failed'}console.warn(e)}
}
async function phase13TestProvider(){const id=document.getElementById('aiProviderTestSelect')?.value||'local';try{const r=await api(`/api/ai/providers/${encodeURIComponent(id)}/test`,{method:'POST',body:'{}'});toast(r.message||'Provider test passed');phase13LoadProviders()}catch(e){toast(e.message||'Provider test failed')}}
function phase13ExternalResult(r){
  const result=r.result||{},action=result.action||r.command?.action||'clarify';let reply='Provider request completed.';let extra='';
  if(action==='list'){const data=result.data||{};reply=`I found ${data.count||0} WebFlow automations.`;extra=phase12FlowCards(data.flows||[])}
  else if(action==='describe'){const f=result.flow;if(f){reply=`${f.name}: ${f.description||'No description.'}`;extra=phase12FlowCards([f])}else reply='I could not resolve that to one WebFlow.'}
  else if(action==='tutorial'){reply='I can open the WebFlow Studio guided tutorial.';extra='<div class="engenie-suggestions"><button data-open-tutorial="1">Open guided tutorial</button></div>'}
  else if(action==='status'){const st=result.status;reply=st?`That job is currently ${st.state}.`:'I could not find that job.'}
  else if(action==='prepare'){const prep=result.preparation||{},missing=prep.missing_parameters||[];if(missing.length){reply='I need some parameters before this flow can run.';extra=`<div class="engenie-flow-card"><b>Parameters needed</b><small>${esc(missing.map(x=>x.name+(x.secret?' (secret)':'')).join(', '))}</small></div>`}else if(prep.confirmation_required){reply='This flow needs your confirmation before it can be queued.';phase12PendingInvocation={flow_id:prep.flow?.flow_id,variables:{},confirmed:true};const c=document.getElementById('engenieConfirm');if(c){document.getElementById('engenieConfirmText').textContent=prep.confirmation_text||`Run ${prep.flow?.name||'this flow'}?`;c.hidden=false}}else{reply='This flow is ready to run.';phase12PendingInvocation={flow_id:prep.flow?.flow_id,variables:{},confirmed:true};extra='<div class="engenie-suggestions"><button data-queue-ready="1">Queue this flow</button></div>'}}
  else if(action==='invoke'){const inv=result.invocation||{};reply=inv.accepted?`Queued successfully. Job ${inv.job_id} is ${inv.state}.`:(inv.message||'The flow was not queued.');if(inv.job_id)extra=`<span class="meta">Ask: status ${esc(inv.job_id)}</span>`}
  else if(action==='clarify')reply=result.message||'Please clarify which WebFlow or action you want.';
  return {reply,extra,action};
}
async function phase12Send(text){
  text=String(text??document.getElementById('engenieInput')?.value??'').trim();if(!text)return;const inp=document.getElementById('engenieInput');if(inp)inp.value='';phase12Msg('You',text);const state=document.getElementById('engenieToolState');if(state)state.textContent='Interpreting request…';
  try{
    const provider=document.getElementById('engenieProvider')?.value||'local';
    if(provider==='local'){
      const r=await api('/api/engenie/message',{method:'POST',body:JSON.stringify({message:text})});let extra='';if(r.action==='list')extra=phase12FlowCards(r.data?.flows||[]);if(r.action==='describe'&&r.flow)extra=phase12FlowCards([r.flow]);if(r.action==='tutorial'&&r.tutorial)extra='<div class="engenie-suggestions"><button data-open-tutorial="1">Open guided tutorial</button></div>';if(r.action==='prepare'&&r.preparation){const prep=r.preparation,missing=prep.missing_parameters||[];if(missing.length)extra=`<div class="engenie-flow-card"><b>Parameters needed</b><small>${esc(missing.map(x=>x.name+(x.secret?' (secret)':'')).join(', '))}</small></div>`;else if(prep.confirmation_required){phase12PendingInvocation={flow_id:prep.flow.flow_id,variables:{},confirmed:true};const c=document.getElementById('engenieConfirm');document.getElementById('engenieConfirmText').textContent=prep.confirmation_text||`Run ${prep.flow.name}?`;c.hidden=false}else{phase12PendingInvocation={flow_id:prep.flow.flow_id,variables:{},confirmed:true};extra='<div class="engenie-suggestions"><button data-queue-ready="1">Queue this flow</button></div>'}}const msg=phase12Msg('Engenie',r.reply||'Done.',extra);phase13WireMessageActions(msg);if(state)state.textContent='Deterministic bridge ready';return;
    }
    const r=await api('/api/ai/message',{method:'POST',body:JSON.stringify({provider_id:provider,message:text})});const view=phase13ExternalResult(r);const msg=phase12Msg(r.provider?.name||'AI Provider',view.reply,view.extra);phase13WireMessageActions(msg);if(state)state.textContent=`${r.provider?.name||provider} → governed tools`;
  }catch(e){phase12Msg('Engenie',e.message||'The provider/tool call failed.');if(state)state.textContent='Provider call failed'}
}
function phase13WireMessageActions(msg){msg?.querySelector('[data-open-tutorial]')?.addEventListener('click',()=>{phase12CloseEngenie();go('replay');toast('Guided tutorial metadata is available to ALM Engenie')});msg?.querySelector('[data-queue-ready]')?.addEventListener('click',phase12ConfirmRun)}
async function phase12ConfirmRun(){if(!phase12PendingInvocation)return;try{const r=await api('/api/engenie/invoke',{method:'POST',body:JSON.stringify(phase12PendingInvocation)});document.getElementById('engenieConfirm').hidden=true;phase12PendingInvocation=null;phase12Msg('Engenie',`Queued successfully. Job ${r.job_id} is ${r.state}.`,`<span class="meta">Ask: status ${esc(r.job_id)}</span>`);phase10Load?.()}catch(e){phase12Msg('Engenie',e.message);if(e.data?.error==='confirmation_required')document.getElementById('engenieConfirm').hidden=false}}
document.getElementById('engenieClose')?.addEventListener('click',phase12CloseEngenie);document.getElementById('engenieBackdrop')?.addEventListener('click',phase12CloseEngenie);document.getElementById('engenieSend')?.addEventListener('click',()=>phase12Send());document.getElementById('engenieInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();phase12Send()}});document.querySelectorAll('[data-engenie-prompt]').forEach(b=>b.addEventListener('click',()=>phase12Send(b.dataset.engeniePrompt)));document.getElementById('engenieConfirmCancel')?.addEventListener('click',()=>{document.getElementById('engenieConfirm').hidden=true;phase12PendingInvocation=null;phase12Msg('Engenie','Run cancelled. No job was queued.')});document.getElementById('engenieConfirmRun')?.addEventListener('click',phase12ConfirmRun);document.getElementById('engenieOpenTools')?.addEventListener('click',async()=>{try{const x=await api('/api/engenie/tools');phase12Msg('Engenie',`The bridge exposes ${(x.tools||[]).length} governed tools.`,(x.tools||[]).map(t=>`<div class="engenie-flow-card"><b>${esc(t.name)}</b><small>${esc(t.method+' '+t.path)}</small></div>`).join(''))}catch(e){toast(e.message)}});document.getElementById('aiProviderRefresh')?.addEventListener('click',phase13LoadProviders);document.getElementById('aiProviderTest')?.addEventListener('click',phase13TestProvider);

