// ---------- Hybrid v4 contextual help ----------
const workspaceHelp={
  designer:{title:'Flow Designer',html:`<p><b>Start with a recording.</b> Selecting a recording loads its browser steps automatically. Keep those browser steps in their recorded order, then add logic around them.</p><p><b>IF / ELSE</b> branches on a variable or output, for example <code>status == "Ready"</code>. <b>For Each</b> repeats its Loop Body for a list such as <code>items</code>. <b>Set Variable</b> creates/calculates a value. <b>Wait</b> adds controlled delay. <b>Python</b> is only for small governed transformations; use <code>variables</code> and <code>outputs</code>, with no imports/files/network. <b>Call Subflow</b> reuses a named block.</p><p>Recorded element locators are edited in <b>Object Repository</b>, not duplicated in the Designer.</p>`},
  objects:{title:'Object Repository',html:`<p>Every interactive element captured by Recorder becomes a reusable object with multiple locator candidates. WebFlow uses these to find the same control during automation.</p><p>Group objects by <b>Recording</b> to see where they came from, or assign a <b>Custom Group Label</b> such as Login, CAB Header, or Results. A higher stability score means the locator is less dependent on fragile page structure.</p><p>If a run clicks the wrong control, open that object and choose a more specific Primary Locator or re-record the interaction.</p>`},
  data:{title:'Data & Variables',html:`<p>This workspace turns a recording into a data-driven automation. First classify recorder steps as <b>Input</b>, <b>Output</b>, <b>Assertion</b>, or <b>Secret</b>. Then upload an Excel/CSV file and map its columns to those variables.</p><p><b>Input</b> supplies a value to the browser. <b>Output</b> reads a value back from the page. <b>Assertion</b> compares the page to an expected value. <b>Secret</b> is supplied at runtime and is not persisted in run JSON.</p><p>After saving the mapping, each selected worksheet row can become an isolated WebFlow run and the result workbook receives status/error/run ID plus mapped outputs.</p>`},
  runs:{title:'Execution Console',html:`<p>This is the real automation run, not Training Replay. Select a saved recording, choose the workstation/Local Client and run it.</p><p>WebFlow resolves each recorded element using semantic identity plus Object Repository locators. Failed steps show fresh evidence and locator diagnostics. Closing the controlled browser before the run finishes marks the run as failed instead of leaving it hanging.</p><p>Use <b>Retry Failed Step</b> after correcting an object locator or page condition.</p>`}
};
function openWorkspaceHelp(id){const h=workspaceHelp[id];if(!h)return;const modal=document.getElementById('workspaceHelpModal');document.getElementById('workspaceHelpTitle').textContent=h.title;document.getElementById('workspaceHelpBody').innerHTML=h.html;modal.hidden=false}
function closeWorkspaceHelp(){const modal=document.getElementById('workspaceHelpModal');if(modal)modal.hidden=true}
