document.getElementById('workspaceHelpClose')?.addEventListener('click',closeWorkspaceHelp);document.getElementById('workspaceHelpModal')?.addEventListener('click',e=>{if(e.target.id==='workspaceHelpModal')closeWorkspaceHelp()});

// ---------- Hybrid v5: authoring ergonomics, layout persistence, table controls ----------
function recordingLabel(r){
  if(!r)return 'Recording';
  const rn=String(r.recording_name||'').trim(), fn=String(r.flow_name||'').trim();
  const generic=/^(new webflow recording|new recording|recorded webflow)$/i;
  if(rn && !generic.test(rn)) return rn;
  if(fn && !generic.test(fn)) return fn;
  try{const host=new URL(r.starting_url||'').hostname.replace(/^www\./,'');if(host)return `Recording · ${host}`;}catch(e){}
  return rn||fn||`Recording ${String(r.id||'').slice(0,8)}`;
}

// Re-declare the recording-backed selectors so every workspace uses the same human-readable name.
async function loadReplayRecordings(){try{replayRecordings=await api('/api/recordings');const sel=document.getElementById('replayRecording');if(!sel)return;const cur=sel.value;sel.innerHTML=replayRecordings.length?replayRecordings.filter(r=>r.steps>0).map(r=>`<option value="${esc(r.id)}">${esc(recordingLabel(r))} • ${r.steps} steps • ${esc((r.started_at||'').slice(0,16).replace('T',' '))}</option>`).join(''):'<option value="">No saved recordings</option>';if(replayRecordings.some(r=>r.id===cur))sel.value=cur;if(sel.value)await loadReplayRecording(sel.value);else renderReplay();}catch(e){toast(`Replay: ${e.message}`)}}
