async function phase6LoadSources(){try{[phase6Recordings,phase6Datasets]=await Promise.all([api('/api/recordings'),api('/api/data/datasets')]);const rs=document.getElementById('dataRecording'),ds=document.getElementById('dataDataset');if(rs){const current=rs.value;rs.innerHTML='<option value="">Select a saved recording</option>'+phase6Recordings.filter(r=>r.steps>0).map(r=>`<option value="${esc(r.id)}">${esc(recordingLabel(r))} • ${r.steps} steps</option>`).join('');if(phase6Recordings.some(r=>r.id===current))rs.value=current}if(ds){const current=ds.value;ds.innerHTML='<option value="">Upload a workbook or CSV</option>'+phase6Datasets.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('');if(phase6Datasets.some(d=>d.id===current))ds.value=current}phase6DataHealth()}catch(e){toast('Data workspace: '+e.message)}}
async function designerSyncFlowSelect(){const sel=document.getElementById('designerFlow');if(!sel)return null;designerRecordings=await api('/api/recordings');const usable=designerRecordings.filter(r=>r.steps>0&&r.flow_id),current=sel.value;sel.innerHTML=usable.length?usable.map(r=>`<option value="${esc(r.flow_id)}" data-recording-id="${esc(r.id)}">${esc(recordingLabel(r))} · ${r.steps} steps</option>`).join(''):'<option value="">No saved recordings yet</option>';if(usable.some(r=>r.flow_id===current))sel.value=current;else if(activeFlowId&&usable.some(r=>r.flow_id===activeFlowId))sel.value=activeFlowId;else if(window.webflowDesignerRecordingId){const hit=usable.find(r=>r.id===window.webflowDesignerRecordingId);if(hit)sel.value=hit.flow_id;}return sel.selectedOptions[0]?.dataset.recordingId||'';}

