document.getElementById('resetRecording')?.addEventListener('click',()=>{if(recorderTimer){clearInterval(recorderTimer);recorderTimer=null}latestRecordingId=null;latestSteps=[];selectedRecordedStepIndex=null;recTargetFlowId=null;document.getElementById('recName').value='New WebFlow Recording';document.getElementById('recUrl').value='https://';const retention=document.getElementById('recRetentionDays');if(retention)retention.value='1';renderRecorderSteps({steps:[]});document.getElementById('browserPreview').classList.remove('has-shot');document.getElementById('browserPreview').innerHTML='<div><div style="font-size:46px;text-align:center">◫</div><b>Local Chromium evidence preview</b><br><span style="font-size:9px">Start a new recording to populate this viewer.</span></div>';setRecorderUI({state:'idle'});toast('Recorder reset — saved recordings were not deleted')});
document.getElementById('deleteRecording')?.addEventListener('click',async()=>{if(!latestRecordingId)return;if(!confirm('Delete this recording and its promoted Draft WebFlow? This cannot be undone.'))return;try{await api('/api/recordings/'+encodeURIComponent(latestRecordingId),{method:'DELETE'});toast('Recording deleted');document.getElementById('resetRecording').click();await loadFlows();await loadObjects();}catch(e){toast(e.message)}});
document.getElementById('continueRecording')?.addEventListener('click',async()=>{if(!latestRecordingId)return;try{const r=await api('/api/recordings/'+encodeURIComponent(latestRecordingId));window.webflowDesignerRecordingId=r.id;activeFlowId=r.flow_id||null;go('designer');}catch(e){toast(e.message)}});

// Object Repository sorting state and stronger group identity.
let v5ObjectSort='name',v5ObjectSortDir=1;
const _v5RenderObjects=renderObjects;
renderObjects=function(){
  const rows=document.getElementById('objectRows'),count=document.getElementById('objectCount');if(!rows||!count)return;
  count.textContent=`${objects.length} object${objects.length===1?'':'s'}`;count.className=`pill ${objects.length?'ready':'draft'}`;
  const groupSelect=document.getElementById('objectGroupMode');if(groupSelect)groupSelect.value=objectGroupMode;
  if(!objects.length){rows.innerHTML='<tr><td colspan="5">No captured objects yet. Record and stop a web process, then return here.</td></tr>';renderObjectDetail(null);return;}
  const grouped={};for(const o of objects){const key=objectGroupMode==='label'?(o.group_label||'Unlabeled'):objectRecordingName(o.source_recording_id);(grouped[key]??=[]).push(o)}
  const val=(o,k)=>k==='stability'?Number(o.stability||0):k==='seen'?Number(o.capture_count||0):String(k==='type'?(o.type||''):(o.name||'')).toLowerCase();
  rows.innerHTML=Object.keys(grouped).sort((a,b)=>a.localeCompare(b)).map(group=>{
    const items=grouped[group].slice().sort((a,b)=>{const av=val(a,v5ObjectSort),bv=val(b,v5ObjectSort);return (av>bv?1:av<bv?-1:0)*v5ObjectSortDir});
    return `<tr class="object-group-row"><td colspan="5"><div class="object-group-title"><span class="object-group-badge">${objectGroupMode==='recording'?'REC':'GROUP'}</span><b>${esc(group)}</b><span>${items.length} object(s)</span></div></td></tr>`+items.map(o=>`<tr data-object-id="${esc(o.id)}" class="${o.id===activeObjectId?'selected-row':''}"><td><b>${esc(o.name)}</b><div class="subtle">${esc(o.accessible_name||o.page_title||'')}</div></td><td>${esc(o.type||'Element')}</td><td class="mono-cell">${esc(o.primary_locator||'—')}</td><td><span class="pill ${stabilityClass(Number(o.stability||0))}">${Number(o.stability||0)}%</span></td><td>${Number(o.capture_count||1)}×</td></tr>`).join('')
  }).join('');
  rows.querySelectorAll('tr[data-object-id]').forEach(r=>r.onclick=()=>{activeObjectId=r.dataset.objectId;renderObjects();renderObjectDetail(objects.find(o=>o.id===activeObjectId));});
  if(!activeObjectId||!objects.some(o=>o.id===activeObjectId))activeObjectId=objects[0].id;renderObjectDetail(objects.find(o=>o.id===activeObjectId));
};
(function addObjectSort(){const gs=document.getElementById('objectGroupMode');if(!gs||document.getElementById('objectSortMode'))return;const s=document.createElement('select');s.id='objectSortMode';s.innerHTML='<option value="name">Sort: Name</option><option value="type">Sort: Type</option><option value="stability">Sort: Stability</option><option value="seen">Sort: Seen</option>';gs.after(s);const d=document.createElement('button');d.className='btn';d.id='objectSortDir';d.textContent='A→Z';s.after(d);s.onchange=()=>{v5ObjectSort=s.value;renderObjects()};d.onclick=()=>{v5ObjectSortDir*=-1;d.textContent=v5ObjectSortDir===1?'A→Z':'Z→A';renderObjects()}})();

// Generic screenshot zoom for Recorder, Replay and Execution evidence.
// "Fit" is the default because the Hub may itself be browser-zoomed or share
// the viewport with two navigation rails. Numeric zoom changes the image's
// layout dimensions (not CSS transform only), so scrollbars always expose the
// full canvas instead of clipping transformed pixels.
const v5Zoom={browserPreview:'fit',replayBody:'fit',runArtifactBody:'fit'};
function v5ApplyZoom(id){const host=document.getElementById(id);if(!host)return;const mode=v5Zoom[id]??'fit';const img=host.querySelector('img');if(img){img.style.transform='none';img.style.margin='0 auto';img.style.objectFit='contain';if(mode==='fit'){img.style.width='auto';img.style.height='auto';img.style.maxWidth='100%';img.style.maxHeight='100%';}else{const scale=Number(mode)||1;const apply=()=>{const w=img.naturalWidth||img.width||1,h=img.naturalHeight||img.height||1;img.style.maxWidth='none';img.style.maxHeight='none';img.style.width=Math.max(1,Math.round(w*scale))+'px';img.style.height=Math.max(1,Math.round(h*scale))+'px';img.style.margin='0';};if(img.complete)apply();else img.addEventListener('load',apply,{once:true});}}const lab=document.querySelector(`[data-zoom-label="${id}"]`);if(lab)lab.textContent=mode==='fit'?'Fit':`${Math.round(Number(mode)*100)}%`;}
document.querySelectorAll('[data-zoom-target]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.zoomTarget,op=b.dataset.zoom;let cur=v5Zoom[id]==='fit'?1:Number(v5Zoom[id]||1);if(op==='reset')v5Zoom[id]='fit';else v5Zoom[id]=Math.max(.35,Math.min(3,cur+(op==='in'?.15:-.15)));v5ApplyZoom(id)}));
['browserPreview','replayBody','runArtifactBody'].forEach(id=>{const el=document.getElementById(id);if(el)new MutationObserver(()=>setTimeout(()=>v5ApplyZoom(id),0)).observe(el,{childList:true,subtree:true})});

// Arrow-key step navigation across Recorder, Replay and Execution evidence.
document.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;const t=e.target;if(t&&['INPUT','TEXTAREA','SELECT'].includes(t.tagName))return;const delta=['ArrowUp','ArrowLeft'].includes(e.key)?-1:1;const active=document.querySelector('.workspace.active')?.id;if(active==='record'&&latestSteps.length){e.preventDefault();let i=selectedRecordedStepIndex==null?latestSteps.length-1:selectedRecordedStepIndex;i=Math.max(0,Math.min(latestSteps.length-1,i+delta));selectedRecordedStepIndex=i;selectRecordedStep(i);document.querySelector(`#recordedSteps [data-step-index="${i}"]`)?.scrollIntoView({block:'nearest'});}else if(active==='replay'&&replayVisibleSteps().length){e.preventDefault();stopReplay();replayIndex=Math.max(0,Math.min(replayVisibleSteps().length-1,replayIndex+delta));renderReplay();document.querySelector('#replayStepList .selected')?.scrollIntoView({block:'nearest'});}else if(active==='runs'&&phase5ActiveRun?.steps?.length){e.preventDefault();const arr=phase5ActiveRun.steps;let i=Math.max(0,arr.findIndex(s=>s.id===phase5SelectedStepId));if(i<0)i=0;i=Math.max(0,Math.min(arr.length-1,i+delta));phase5SelectedStepId=arr[i].id;phase5RenderArtifact(arr[i]);document.querySelector(`[data-run-step="${CSS.escape(phase5SelectedStepId)}"]`)?.scrollIntoView({block:'nearest'});}});

// Generic table toolkit: search/filter, CSV export, density, sortable headers and resizable columns.
function v5Csv(table){const rows=[...table.querySelectorAll('tr')].filter(r=>!r.classList.contains('object-group-row')&&r.offsetParent!==null);return rows.map(r=>[...r.children].map(c=>'"'+String(c.innerText||'').replace(/"/g,'""').replace(/\n/g,' ')+'"').join(',')).join('\n')}
function v5InitTable(table,index){if(table.dataset.tableEnhanced)return;table.dataset.tableEnhanced='1';const host=table.closest('.table-scroll')||table.parentElement;const tools=document.createElement('div');tools.className='table-tools';tools.innerHTML=`<input type="search" placeholder="Filter table…" aria-label="Filter table"><span class="table-row-count"></span><button class="btn" data-density="1">Compact</button><button class="btn" data-export="1">Export CSV</button>`;host.parentElement?.insertBefore(tools,host);const search=tools.querySelector('input'),cnt=tools.querySelector('.table-row-count');function filter(){const q=search.value.trim().toLowerCase(),body=[...table.tBodies].flatMap(b=>[...b.rows]);let shown=0;body.forEach(r=>{if(r.classList.contains('object-group-row'))return;const ok=!q||r.innerText.toLowerCase().includes(q);r.hidden=!ok;if(ok)shown++});cnt.textContent=`${shown} row${shown===1?'':'s'}`;if(table.classList.contains('object-table')){[...table.querySelectorAll('.object-group-row')].forEach(g=>{let n=g.nextElementSibling,any=false;while(n&&!n.classList.contains('object-group-row')){if(!n.hidden)any=true;n=n.nextElementSibling}g.hidden=!any})}}search.oninput=filter;tools.querySelector('[data-density]').onclick=e=>{table.classList.toggle('compact-table');e.currentTarget.textContent=table.classList.contains('compact-table')?'Comfortable':'Compact'};tools.querySelector('[data-export]').onclick=()=>{const blob=new Blob([v5Csv(table)],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`webflow-table-${document.querySelector('.workspace.active')?.id||index}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};[...table.tHead?.rows?.[0]?.cells||[]].forEach((th,col)=>{th.classList.add('sortable-th');const res=document.createElement('span');res.className='col-resizer';th.appendChild(res);res.onpointerdown=ev=>{ev.stopPropagation();ev.preventDefault();const start=ev.clientX,w=th.offsetWidth;const move=x=>{th.style.width=Math.max(55,w+x.clientX-start)+'px';th.style.minWidth=th.style.width};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up)};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up)};th.addEventListener('click',ev=>{if(ev.target===res||table.classList.contains('object-table'))return;const body=table.tBodies[0];if(!body)return;const dir=th.dataset.sortDir==='asc'?-1:1;[...table.tHead.querySelectorAll('th')].forEach(x=>delete x.dataset.sortDir);th.dataset.sortDir=dir===1?'asc':'desc';[...body.rows].sort((a,b)=>{const av=a.cells[col]?.innerText.trim()||'',bv=b.cells[col]?.innerText.trim()||'';const an=parseFloat(av.replace(/[^0-9.-]/g,'')),bn=parseFloat(bv.replace(/[^0-9.-]/g,''));const cmp=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:av.localeCompare(bv,undefined,{numeric:true});return cmp*dir}).forEach(r=>body.appendChild(r));filter()})});new MutationObserver(filter).observe(table,{childList:true,subtree:true});filter();}
function v5EnhanceTables(){document.querySelectorAll('table.table').forEach(v5InitTable)}

// User layout system. Major cards/panels can be reordered within their current container and resized.
const V5_LAYOUT_KEY='webflow-layout-v5:';
function v5TileKey(tile,i){const ws=tile.closest('.workspace')?.id||'global';return tile.dataset.tileKey||(tile.dataset.tileKey=`${ws}:${tile.id||tile.classList[0]||'tile'}:${i}`)}
function v5EnhanceTiles(){document.querySelectorAll('.workspace').forEach(ws=>{const tiles=[...ws.querySelectorAll('.panel, .recorder-setup, .hybrid-boundary-note, #record .steps, #record .browser, #record .inspector')];tiles.forEach((tile,i)=>{if(tile.dataset.tileEnhanced)return;tile.dataset.tileEnhanced='1';tile.classList.add('user-tile');v5TileKey(tile,i);const h=document.createElement('div');h.className='tile-grip';h.title='Drag to rearrange this tile';h.textContent='⋮⋮';tile.prepend(h);h.addEventListener('pointerdown',()=>tile.draggable=true);tile.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',tile.dataset.tileKey);tile.classList.add('dragging')});tile.addEventListener('dragend',()=>{tile.draggable=false;tile.classList.remove('dragging')});tile.addEventListener('dragover',e=>e.preventDefault());tile.addEventListener('drop',e=>{e.preventDefault();const key=e.dataTransfer.getData('text/plain'),src=document.querySelector(`[data-tile-key="${CSS.escape(key)}"]`);if(src&&src!==tile&&src.parentElement===tile.parentElement)tile.parentElement.insertBefore(src,tile);});});v5RestoreLayout(ws.id)});}
function v5LayoutSnapshot(ws){return [...ws.querySelectorAll('.user-tile')].map((t,i)=>({key:t.dataset.tileKey,parent:t.parentElement?.className||'',order:i,width:t.style.width||'',height:t.style.height||''}))}
function v5SaveLayout(){const ws=document.querySelector('.workspace.active');if(!ws)return;localStorage.setItem(V5_LAYOUT_KEY+ws.id,JSON.stringify(v5LayoutSnapshot(ws)));toast(`Saved ${names[ws.id]||ws.id} layout`)}
function v5RestoreLayout(id){const ws=document.getElementById(id);if(!ws)return;let data;try{data=JSON.parse(localStorage.getItem(V5_LAYOUT_KEY+id)||'null')}catch(e){}if(!Array.isArray(data))return;const map=new Map(data.map(x=>[x.key,x]));[...ws.querySelectorAll('.user-tile')].forEach(t=>{const d=map.get(t.dataset.tileKey);if(d){t.style.width=d.width||'';t.style.height=d.height||''}});const groups=new Map();[...ws.querySelectorAll('.user-tile')].forEach(t=>{const p=t.parentElement;if(!groups.has(p))groups.set(p,[]);groups.get(p).push(t)});groups.forEach((tiles,p)=>tiles.sort((a,b)=>(map.get(a.dataset.tileKey)?.order??999)-(map.get(b.dataset.tileKey)?.order??999)).forEach(t=>p.appendChild(t)))}
function v5ResetLayout(){const ws=document.querySelector('.workspace.active');if(!ws)return;localStorage.removeItem(V5_LAYOUT_KEY+ws.id);ws.querySelectorAll('.user-tile').forEach(t=>{t.style.width='';t.style.height='' });toast('Default layout restored');setTimeout(()=>location.reload(),250)}
document.getElementById('saveLayoutView')?.addEventListener('click',v5SaveLayout);document.getElementById('resetLayoutView')?.addEventListener('click',v5ResetLayout);

// Keep enhancements alive as dynamic tables/workspaces render.
const _v5Go=go;go=function(id){_v5Go(id);setTimeout(()=>{v5EnhanceTiles();v5EnhanceTables();v5RestoreLayout(id)},0)};
v5EnhanceTiles();v5EnhanceTables();
